2. {"type": "cafe", "properties": {"tags": ["coffee", "cocktails", "beer", "wine", "city_center"], "outdoor_seating": true, "indoor_seating": true, "name": "Caffe Bar Uliks", "phone": "+385 52 219 158", "opening_hours": "Mo-Su 07:00-02:00", "addr:housenumber": "1", "addr:street": "Trg Portarata", "rating": 4.5, "description": "A historic café bar in the very center of Pula, right next to the Arch of the Sergii, known for its literary connection to James Joyce, a wide drinks selection, specialty local spirits and craft beers, and a lively atmosphere with quizzes and other events.", "reviews": ["Would highly recommend! Really nice people inside and great vibes. The decor is so cool!", "Really lovely small pub, 10/10 would recommend for a quick pint. Cool statue of James Joyce outside who used to teach English in the building back yonder.", "Best place to watch Pula‘s life, friendly service, reasonable prices, my recommendation: the Negroni", "A nice cup of coffee on a beautiful spot next to the Arch of the Sergii."], "price": "medium"}}
3. {"type": "cafe", "properties": {"tags": ["coffee", "wine", "cocktails", "city_center"], "outdoor_seating": true, "indoor_seating": true, "name": "Sirena", "phone": null, "opening_hours": "Mo-Fr 08:00-24:00; Sa-Su 09:00-24:00", "addr:housenumber": "12", "addr:street": "Forum", "rating": 4.1, "description": "A relaxed café on Pula’s main square, offering coffee, wine, cocktails, and terrace seating with views of the historic Forum.", "reviews": ["Wonderful place for coffee or a glass of delicious wine, with a view of the beautiful buildings around Forum Square. During our visits, we had the pleasure to meet waitress with long, slightly wavy hair — she was sooo cool and perfectly handled all orders. We'd love to come back! ❤️", "Nice terrace on the square! During the day, lots of shadow because of the wide parasols! The square is open, don’t get sunburned !", "Nice place, amazing coctails and lovely staff!"], "price": null}}
4. {"type": "cafe", "properties": {"tags": ["coffee", "beer", "city_center"], "outdoor_seating": true, "indoor_seating": true, "name": "Scala", "phone": "+385 98 898 484", "opening_hours": null, "addr:housenumber": "1", "addr:street": "Ozad Arene", "rating": 4.0, "description": "A simple café bar right next to the Pula Arena, best known for its unique terrace with a direct view of the amphitheatre. It is a relaxed spot for coffee or a drink in one of the city’s most iconic locations.", "reviews": ["Perfect place to watch the Arena and enjoy a cold drink! Personnel is nice and friendly. Prices are regular. Have you never visited Croatia before? Try Pasareta, a real Croatian drink! 💪🏼 with lots of ice cubes, perfect! We only had drinks, no food. They have a lot of ice creams!", "Great coffee bar / drinks. Best spot in the area for a quiet coffee and to enjoy the arena. The staff all spoke many languages and were very helpful on giving local recommendations.", "Service extremely friendly and attentive. Nice ambience (with music from the amphitheater). Just perfect, where you feel comfortable and enjoy the sunset. Can only recommend👌"], "price": "medium"}}
5. {"type": "marina", "properties": {"name": "ACI Marina Pula", "tags": ["marina", "city_center", "restaurant", "near_attractions"], "description": "City marina in the heart of Pula, known for its protected harbour setting, full nautical services, boat rentals, and unique views of the Roman Arena.", "rating": 4.3, "reviews": ["ACI Marina in Pula is a top-notch spot for boaters and visitors alike. Well-maintained docks, friendly staff, and beautiful views make it perfect for sailing, relaxing by the water, or enjoying nearby cafes and restaurants.", "Very good Marina restaurant, helpful and friendly Marinero. Clean sanitary facilities, in the middle of the city. Can be noisy sometimes. Marina ist best contacted if you are already quite near if via VHF. Mobile phone is also possible.", "The marina is nice and spacious. You can walk above the coast and admire the boats and views."]}}

1. {"type": "fort", "properties": {"name": "Fort Punta Christo", "tags": ["fortress", "historic", "coastal", "underground", "events", "military_history"], "description": "Circular fort built in the late 1800s with underground rooms, also a venue for music festivals.", "rating": 4.3, "reviews": null}}
2. {"type": "fort", "properties": {"name": "Fort Tegetthoff", "tags": ["fortress", "historic", "military_history", "coastal", "closed_area", "national_park", "island"], "description": "Large circular Austro-Hungarian coastal fort on Veliki Brijun, preserved under military control and closed to visitors.", "rating": null, "reviews": null}}
3. {"type": "fort", "properties": {"name": "Fort Brioni Minor", "tags": ["fortress", "historic", "coastal", "military_history", "national_park", "island", "events"], "description": "Large Austro-Hungarian coastal fortress on Mali Brijun, known for its preserved military architecture, strategic sea-facing position, and summer theatre performances held within the fort.", "rating": 4.8, "reviews": ["We have a chance to enjoy there as part of the King Lear play. Fortress is amasing an perfectly fitted the show.", "Amazing still standing fortress from the beginning of 20th century. Used by Ulysses theatre", "A beautiful place, lots of wonderful things to see, from rich flora and fauna to beautiful historical buildings."]}}
4. {"type": "fort", "properties": {"name": "Fort Grosso", "tags": ["fortress", "historic", "hilltop", "military_history"], "description": "Historic hilltop fortress on Monte Grosso near Štinjan, known for its early military role in Pula’s defence system, preserved circular form, forest setting, and wide views towards the Brijuni area.", "rating": 4.6, "reviews": ["One of the 19th century artillery forts around Pula. Partly conserved, it is possible to enter and explore it and to climb the staircase to the platform. It is still astonishing despite being neglected in all ways.", "Quite far from Pula. There are some nice places for mountain biking around here. To get to the fort you'll need to go off the main road at a point. There, Google Maps will get a little lost but just keep going on this dirt road. At a point you will find a sign with some info about the fort and there you are. Don't let the closed blue gate scare you, the entrance to the fort is to it's right. Quite the nice place. Awesome views.", "A majestic view from here! I think it's the best view among all those local towers. It is a few steps from Stinjan, but worth visiting, as well as going further to the fort closer to the sea (Valmaggiore)", "Nestled atop the city’s lush hill, the fortress offers a glimpse into Pula’s captivating past, intertwined with stories of power, conquest, and resilience. When I visited not long ago, the wear and tear were evident, and parts of the fortress have collapsed. While it poses certain risks, history enthusiasts may find the journey worthwhile. However, if you choose to visit, please proceed at your own risk and exercise caution, but those who go there will not regret it."]}}
5. {"type": "fort", "properties": {"name": "Fort Verudella", "tags": ["fortress", "historic", "coastal", "aquarium", "military_history", "family_friendly"], "description": "19th-century coastal fortress on Punta Verudela, now home to Aquarium Pula and known for its military heritage and sea-facing setting.", "rating": null, "reviews": null}}

1. {"type": "park", "properties": {"name": "Park Sergio Endrigo", "tags": ["park", "memorial", "near_attractions", "city_center"], "description": "Small urban park in central Pula dedicated to singer-songwriter Sergio Endrigo, with commemorative installations and occasional cultural events. Today it is mostly a quiet stop with a few benches and greenery, more suitable for a short pause than as a main attraction.", "rating": null, "reviews": null}}
2. {"type": "artwork", "properties": {"name": "Spomenik streljanim mornarima", "tags": ["sculpture", "monument", "memorial", "historic", "city_center", "near_attractions"], "description": "Memorial sculpture in Valerijin park in Pula, dedicated to the sailor and associated with the remembrance of the 1918 sailors’ revolt in the Bay of Kotor.", "rating": null, "reviews": null}}
3. {"type": "artwork", "properties": {"name": "Marko Marulić", "tags": ["statue", "sculpture", "monument", "park", "artwork", "city_center"], "description": "A bronze public sculpture dedicated to one of the most important figures of Croatian literature, placed in a small park near the waterfront and the railway station. Its calm, dignified form reflects the intellectual and cultural legacy of the Renaissance writer, adding a literary and commemorative note to the surrounding urban landscape.", "rating": 4.0, "reviews": null}}
4. {"type": "restaurant", "properties": {"tags": ["pizza", "neapolitan_pizza", "italian", "vegetarian", "city_center"], "outdoor_seating": true, "indoor_seating": true, "name": "Pizzeria Piccolo Porto", "phone": "+385 52 851 258", "opening_hours": "Mo-Su 12:00-23:00", "addr:housenumber": "11", "addr:street": "Porta Stovagnaga", "rating": 4.4, "description": "A cozy pizzeria in old town serving authentic Neapolitan pizza in a warm and inviting setting. Known for its long-fermented dough, Italian ingredients, and classic pizzas like Margherita and Diavola, it is a great spot for a true taste of Naples in the city center.", "reviews": ["We've enjoyed lunch here on 3 days. The reasons we kept returning; plenty of choice with traditional dishes to the region on the menu, the food is delicious, waiter Eva is welcoming and really helpful in guiding us through the menu, the lunch price is great value. Toilets were very clean too. Highly recommend.", "Hands down the best Neapolitan pizza in town! I’ve tried every pizzeria around, and nothing comes close to this gem. The ingredients are super fresh, the dough is light, soft in the center, and perfectly crispy on the edges, just like true Neapolitan tradition. Every bite is a burst of authentic flavors! The staff is mega friendly, and the vibe of the street is amazing. If you’re craving real Neapolitan pizza, this is THE spot. Highly recommend! 🍕🔥", "Truly the best pizza I have ever eaten — not an exaggeration. The owner is so nice and accommodating, and the food is fresh, local, and delicious. You have to come here if you are in Pula.", "Great pizza with good choice of salad and also dishes like kalamari, fish and chips and fried chicken cutlets right in the heart of the city!"], "price": null}}
5. {"type": "restaurant", "properties": {"tags": ["pizza", "city_center", "vegetarian"], "outdoor_seating": false, "indoor_seating": true, "name": "Pizza alla Nonna", "phone": "+385 95 764 5920", "opening_hours": "Mo-Su 10:00-22:00", "addr:housenumber": "3", "addr:street": "Istarska", "rating": 4.6, "description": "A casual pizzeria in the city center, popular for pizza by the slice as well as whole pizzas. It is a convenient spot for a quick bite, especially for people looking for simple, affordable pizza in a relaxed setting.", "reviews": ["Found this place during sight seeing tour! Only 5 minutes by foot away from the popular amphi-theater! Outstanding place with delicious housemadePizza! Prices are really reasonsble!!! Friendly stuff too!", "the pizza is huge and delicious! €2 for a massive slice (see picture:)) the staff were friendly. there is some seating inside but not loads, it’s clean and open - a toilet too i think", "By far the best en biggest pizza we ever had. For a fair price (€15 for a big big one) would recommend to anyone💪🏼"], "price": "low"}}

1. {"type": "monument", "properties": {"name": "Slavoluk Sergijevaca", "tags": ["monument", "roman", "historic", "landmark", "city_center"], "description": "Historic Roman arch in central Pula, known as the Arch of the Sergii or Golden Gate, famous for its ornate reliefs and long-standing civic significance.", "rating": 4.6, "reviews": ["The Golden Gate in Pula is a beautifully preserved historic landmark. Its Roman architecture and detailed stonework make it a must-see in the city center. A great spot for a quick walk, photos, and soaking in the ancient atmosphere.", "A Roman triumphal arch, beautifully intact through the ages. Its intricate carvings reflect the artistry of the Augustan era, while its enduring form stands as a testament to the power and legacy of ancient Rome.", "Beautiful Roman arch in the heart of Pula. The Arch of the Sergii is a stunning reminder of the city's ancient past. Great spot for photos and easy to find while walking through the old town.", "Another beautiful piece of history which must be seen to be appreciated when you’re in Pula. Seems to be the main entrance essentially to the late ish night shops and restaurants/bars etc. Did have a nice jazz band situated here one night too!"]}}
2. {"type": "cafe", "properties": {"tags": ["coffee", "pub", "beer", "city_center"], "outdoor_seating": true, "indoor_seating": true, "name": "Bounty", "phone": "+385 52 218 088", "opening_hours": "Mo-Su 07:00-23:00", "addr:housenumber": "8", "addr:street": "Veronska", "rating": 4.6, "description": "A cozy Irish-style pub in city center, known for draft beer, a wide drink selection, and a comfortable terrace with a relaxed atmosphere.", "reviews": ["An excellent Irish pub with a great Irish atmosphere. Clean, tidy, good to be here As it is a bit away from the busy tourist area, it is not crowded. Guinness and local beers on tap, plus a great selection of drinks. Shaded, comfortable terrace.", "Didn't get to stay here for long (one drink) however it has a real homely feel to the place and is a really nicely situated pub. Good atmosphere and seating options, good drink choices which are more foreign options (Guinness/Heineken/Jack Daniels etc) and the prices are quite good also! Would recommend stopping in for some drinks if in the local area!", "This is a proper bar. Beautiful inside. A nice seating area outside. They have a really good selection of drinks on offer."], "price": null}}
3. {"type": "zoo", "properties": {"name": "Fazanerija", "tags": ["zoo", "animals", "family_friendly", "national_park", "island"], "description": "Small animal and bird area where visitors can see peacocks, turkeys, guinea fowl, parrots, and other birds, while the site also serves as a recovery and temporary care center for wild animals.", "rating": 4.1, "reviews": ["Don’t miss seeing this bird! Easy to find, unique experience", "Koji is awesome! He knows a few words, best one being 'tito'", "The animals seem content, and the facility was well-maintained. Of course, the buildings are old, and it's not a large zoo. But it's definitely worth a visit."]}}
4. {"type": "pub", "properties": {"tags": ["coffee", "cocktails", "beer", "nightlife", "city_center"], "outdoor_seating": true, "indoor_seating": true, "name": "Old City Bar", "phone": "+385 52 222 944", "opening_hours": "Mo-Fr 06:30-02:30; Sa 07:00-02:00; Su 08:30-2:30", "addr:housenumber": "1", "addr:street": "Danteov trg", "rating": 4.5, "description": "A pub located in the center of Pula, offering a relaxed atmosphere during the day and lively parties at night. It is a popular spot for drinks, socializing, and weekend nightlife.", "reviews": ["Great service, Marcus was attentive and funny and made our night!! Drinks were all very good and really enjoyed the theatrics of the different shots and cocktails.", "Best Cocktails in town and super cool service personal, Marcus is our man! Come here! ✨🙌", "The service in this place cannot be compared to anything I've experienced so far of my nine days in Croatia. Not the cheapest, but the persistence and effort by Marco is why you pay a premium. The live music was also quite good. Awsome Bloody Mary if you're into that, and a selection of craft beer if that is your thing. (To Marco's employer, you should give this man a raise)"], "price": "medium"}}
5. {"type": "fort", "properties": {"name": "Fort Punta Christo", "tags": ["fortress", "historic", "coastal", "underground", "events", "military_history"], "description": "Circular fort built in the late 1800s with underground rooms, also a venue for music festivals.", "rating": 4.3, "reviews": null}}

1. {"type": "city_gate", "properties": {"name": "Herkulova vrata", "tags": ["city_gate", "monument", "roman", "historic", "city_center", "landmark"], "description": "Ancient Roman city gate in Pula, known as the city’s oldest preserved Roman architectural monument, with a carved head of Hercules and an inscription linked to the founding of the Roman colony.", "rating": 4.3, "reviews": ["Small but historic. The Hercules Gate is easy to miss, but worth a quick stop. Ancient Roman carvings still visible—great for history lovers!", "Cool history, worth routing your walking path on your way to some of the more popular spots in Pula.", "The historical plaque is on the inside of the gate, making it hard to find, but still very picturesque."]}}
2. {"type": "park", "properties": {"name": "Park Sergio Endrigo", "tags": ["park", "memorial", "near_attractions", "city_center"], "description": "Small urban park in central Pula dedicated to singer-songwriter Sergio Endrigo, with commemorative installations and occasional cultural events. Today it is mostly a quiet stop with a few benches and greenery, more suitable for a short pause than as a main attraction.", "rating": null, "reviews": null}}
3. {"type": "zoo", "properties": {"name": "Fazanerija", "tags": ["zoo", "animals", "family_friendly", "national_park", "island"], "description": "Small animal and bird area where visitors can see peacocks, turkeys, guinea fowl, parrots, and other birds, while the site also serves as a recovery and temporary care center for wild animals.", "rating": 4.1, "reviews": ["Don’t miss seeing this bird! Easy to find, unique experience", "Koji is awesome! He knows a few words, best one being 'tito'", "The animals seem content, and the facility was well-maintained. Of course, the buildings are old, and it's not a large zoo. But it's definitely worth a visit."]}}
4. {"type": "artwork", "properties": {"name": "James Joyce", "tags": ["artwork", "statue", "historic", "city_center", "landmark", "near_attractions"], "description": "Bronze statue of James Joyce in central Pula near the Arch of the Sergii, commemorating the famous Irish writer’s stay in the city and its place in his early literary life.", "rating": 4.7, "reviews": ["This statue made we search more about this Irish novelist. He was an important writer whose books are read today. Here you can take selfies with the statue and enjoy a cup of coffee in a table next to the statue.", "Nice sculpture. Beside a restaurant. If not known, or checked carefully, one can miss it for a person waiting outside a restaurant.", "Nice statue. You can sit with him."]}}
5. {"type": "park", "properties": {"name": "Park Monte Zaro", "tags": ["park", "historic", "hilltop", "observatory", "city_center", "family_friendly", "playground"], "description": "Largest historic park in Pula, set on a hill around the observatory, with fountains, Mediterranean trees, and scenic views over the city and harbour.", "rating": 4.5, "reviews": ["I didn’t expect much, but Montezaro Park turned out to be such a nice surprise. It’s quiet, full and perfect when you need a break from the heat and crowds. I grabbed a coffee and just walked around for a bit…. really relaxing spot with a great local feel.", "The roots of Montezaro Park are deeply embedded in Pula’s past. Originally designed in the 19th century, it was a retreat for nobility and a symbol of prestige. Small park that has a fountain, many trails to get around, and plenty of flora areas to enjoy. It's on a small hill so you can get some views of the surrounding area.", "A quiet city park on a hill overlooking Pula harbour, a welcome escape far from the madding crowd."]}}

1. {"type": "fort", "properties": {"name": "Tvrđava Muzil", "tags": ["fortress", "historic", "hilltop", "coastal", "military_history"], "description": "Historic circular fortress on the Muzil peninsula in Pula, known for its preserved Austro-Hungarian military architecture, panoramic sea views, and prominent position above the southern coast.", "rating": 4.3, "reviews": ["I'm happy that this most preserved Pula's fort is now locked and secured, preventing it from robbing and vandalism. Thanks.", "It was nice 'urban exploring' adventure, ruins everywhere, protected by army, but guardian is nice and army too! When sun goes down, be fast. Minutes matters. Some bushes (makija) can be spiky! Avoid them. Don't be barefoot.", "Fort Muzil is closed to free entry from December 30, 2022. The facility is protected and maintained and can only be visited with prior notice or an organized tour."]}}
2. {"type": "restaurant", "properties": {"tags": ["international", "mediterranean", "seafood", "wine", "desserts"], "outdoor_seating": true, "indoor_seating": true, "name": "Ribarska Koliba", "phone": "+385 99 499 1306", "opening_hours": "Mo off; Tu-Th 13:00-20:00; Fr-Sa 13:00-21:00; Su 13:00-20:00", "addr:housenumber": "3", "addr:street": "Verudela", "rating": 3.9, "description": "A refined seaside restaurant known for fresh local seafood, Mediterranean cuisine, Istrian wines, homemade desserts, and elegant dining with a sea view.", "reviews": ["A culinary highlight! The dishes are creative, refined and simply taste convincing. The service is friendly and attentive, the ambience warm and welcoming – perfect for a relaxed lunch or dinner. A little downer: The plates were cold, so the food quickly became lukewarm. Nevertheless, an all-round recommended visit!", "Exceptional food and service ⭐️⭐️⭐️⭐️⭐️ Best lubina, stuffed swuid was excellent as well! Lovely setting for an evening meal.", "Nice view and good food! The only downside was that the main course came pretty soon after the starter. As a result, we were basically ready within an hour. We had to wait the longest for the bill 😅"], "price": null}}
3. {"type": "fort", "properties": {"name": "Utvrda Marie Louise", "tags": ["fortress", "historic", "coastal", "panoramic_view", "military_history"], "description": "Large 19th-century coastal fortress on the Muzil peninsula in Pula, known for its circular design and strategic views over the bay entrance.", "rating": 4.4, "reviews": ["The remains of a large defensive fort on Musil peninsula. It was built in the 19th century and used by different armies throughout history. Today it is almost forgotten but still far from a mere ruin. The strength of its walls and beauty of its architecture are still evident. It is safe to explore, yet watch your step for scrap metal, holes and other obstacles. Just like Verudela this ruin should be restored and put to good use.", "Spectacular abandoned fort. You can explore everything. Be careful.", "There's a good, convenient entrance, but it's guarded. Closed to the curious. However, you can access the area along the western coast along a narrow path. Along the way, you'll encounter abandoned former military fortifications. It's a bit scary! Once inside, I felt like a stalker! I saw several huge peacocks. This was once a huge military base. Now everything is abandoned, but the buildings, both above and below ground, are in excellent condition."]}}
4. {"type": "castle", "properties": {"name": "Fort Stoja", "tags": ["fortress", "historic", "coastal", "military_history", "closed_area"], "description": "Historic coastal fortress on the Stoja peninsula in Pula, built as part of the Austro-Hungarian defence system and known for its preserved military architecture and strategic position above the southern approach to the harbour.", "rating": 4.4, "reviews": ["Very beautiful places with the opportunity to jump from cliffs.", "I unexpectedly discovered this place, a mound. Fort Stoja is one of the most mysterious and 'hidden' forts in Pula. Built in 1884 by the Austro-Hungarians as part of a powerful coastal defense for the empire's main naval base. Unlike most forts, Stoja is almost completely dug into the peninsula's limestone cliff: only a massive entrance wall with a portal is visible from the outside, while the rest is hidden underground and covered by a dense pine forest. It is surrounded by a deep moat cut into the rock, once filled with water and protected by caponiers. On three sides, the fort plunges directly into the sea, making it virtually invisible from the water or from the air. Inside are long casemates, powder magazines, and posterns extending into the hillside. After the First World War, it lost its military significance and gradually became overgrown with forest, becoming a 'ghost fort.' Today the moat is dry, but the walls and entrance are impressive: it seems as if the mountain itself opens a huge door to the 19th century. An ideal place for those who enjoy the atmosphere of abandoned fortifications, peace and quiet, and views of the Adriatic without the crowds of tourists.", "Beautiful campsite, convenient for Pula by bus. The fort is not accessible and is at the top of the peninsula."]}}
5. {"type": "cafe", "properties": {"tags": ["coffee", "smoothies", "healthy", "brunch", "breakfast", "international", "vegan", "vegetarian", "gluten_free"], "outdoor_seating": true, "indoor_seating": true, "name": "Kavana Lattiera", "phone": "+385 91 537 4711", "opening_hours": "Mo-Fr 08:00-16:00; Sa-Su 09:00-15:00", "addr:housenumber": "4", "addr:street": "Trg Kralja Tomislava", "rating": 4.8, "description": "A modern cafe in Veruda known for specialty coffee, healthy breakfasts, smoothie bowls, homemade cakes, and a relaxed neighborhood atmosphere. Inspired by Berlin-style coffee culture, it is a popular spot for morning coffee, brunch, fresh juices, and casual meetups on the square.", "reviews": ["We stopped at Kavana Lattiera and really enjoyed the atmosphere. The coffee and desserts were excellent, and the place has a very nice vibe for sitting down and relaxing. One thing that stood out, though, was the wait time – we had to wait more than 30 minutes for our order, and it felt like we had been forgotten for a while. Once everything finally arrived, the quality made up for it, but the service could definitely be more attentive.", "Great place with a fresh and healthy offer! The menu is full of delicious options made from quality ingredients — from smoothie bowls and sandwiches to great breakfast choices. The açaí bowl is especially tasty and definitely worth trying. Perfect spot for a relaxed coffee or a healthy meal.", "During the vacation with my girlfriend (who only eats vegetarian and gluten free) in Croatia, we went a couple of times here. What a nice place and so many locals went there as well. The menu was only on Croatian and we had to translate but that was not a problem at all. The service, the food, everything is so nice here. And the best thing is, it’s open until 4 pm.", "Very interesting establishment set amongst apartments and shops. Inside it's a whole different feel to the outside and to what I have seen in Pula, which is very comforting and reminds me of other international cafes, and those special couple of cafes in Zagreb too. The food is so good, healthy and very thoughtful recipes. Veg will be happy. Oat milk available."], "price": "medium"}}

1. {"type": "zoo", "properties": {"name": "Fazanerija", "tags": ["zoo", "animals", "family_friendly", "national_park", "island"], "description": "Small animal and bird area where visitors can see peacocks, turkeys, guinea fowl, parrots, and other birds, while the site also serves as a recovery and temporary care center for wild animals.", "rating": 4.1, "reviews": ["Don’t miss seeing this bird! Easy to find, unique experience", "Koji is awesome! He knows a few words, best one being 'tito'", "The animals seem content, and the facility was well-maintained. Of course, the buildings are old, and it's not a large zoo. But it's definitely worth a visit."]}}
2. {"type": "park", "properties": {"name": "Titov park", "tags": ["park", "city_center", "memorial", "events", "historic", "family_friendly", "playground", "near_attractions"], "description": "Central waterfront park in Pula, known for its memorial monuments, shaded walking areas, city model, and lively social atmosphere with seasonal events.", "rating": 4.5, "reviews": ["Tito's Park in Pula is a prominent public park that serves as a green oasis in the heart of the city. Named after Josip Broz Tito, the former Yugoslav leader, the park is a popular area for both locals and tourists seeking relaxation and recreation. There's also a miniature model on one side of the park.", "Nice park next to the water with many busts of famous partisans, including Tito. The main monument is also dedicated to the partisans. Worth a few pictures.", "A piece of more recent Croatian history. Has some statues, a place for kids to play, a few benches and a model of the city."]}}
3. {"type": "park", "properties": {"name": "Park Monte Zaro", "tags": ["park", "historic", "hilltop", "observatory", "city_center", "family_friendly", "playground"], "description": "Largest historic park in Pula, set on a hill around the observatory, with fountains, Mediterranean trees, and scenic views over the city and harbour.", "rating": 4.5, "reviews": ["I didn’t expect much, but Montezaro Park turned out to be such a nice surprise. It’s quiet, full and perfect when you need a break from the heat and crowds. I grabbed a coffee and just walked around for a bit…. really relaxing spot with a great local feel.", "The roots of Montezaro Park are deeply embedded in Pula’s past. Originally designed in the 19th century, it was a retreat for nobility and a symbol of prestige. Small park that has a fountain, many trails to get around, and plenty of flora areas to enjoy. It's on a small hill so you can get some views of the surrounding area.", "A quiet city park on a hill overlooking Pula harbour, a welcome escape far from the madding crowd."]}}
4. {"type": "fort", "properties": {"name": "Mletačka utvrda", "tags": ["fortress", "historic", "panoramic_view", "city_center", "events", "concerts"], "description": "French-style defensive fortress built by the Venetians in the 1600s, with views of the city & bay.", "rating": 4.5, "reviews": ["Amazing views from the top - panoramic of the whole site - was helpful as my first look of the city to get my bearings. Loved that the ticket also included use of the undercity tunnel network - helpful as it was raining on and off (visited a couple of days ago!)", "Very beautiful views. Nice fortress, with a tower from where the views are even more wonderful. The entrance fee is 7 euros.", "I like history and I've been to quite a few other fortresses and the design follows other fortress designs because you're trying to defend and required similar designs and systems. The fortress has been disarmed and the museums/displays on site are bright with information and displays but I found some lack.....that is not a bad comment, just a minor con. There has obviously been a lot of work to maintain the integrity of the stone work and that is definitely a pro. Definitely worth the time for a visit. I rate this 4 stars."]}}
5. {"type": "cafe", "properties": {"tags": ["coffee", "cocktails", "beer", "wine", "city_center"], "outdoor_seating": true, "indoor_seating": true, "name": "Caffe Bar Uliks", "phone": "+385 52 219 158", "opening_hours": "Mo-Su 07:00-02:00", "addr:housenumber": "1", "addr:street": "Trg Portarata", "rating": 4.5, "description": "A historic café bar in the very center of Pula, right next to the Arch of the Sergii, known for its literary connection to James Joyce, a wide drinks selection, specialty local spirits and craft beers, and a lively atmosphere with quizzes and other events.", "reviews": ["Would highly recommend! Really nice people inside and great vibes. The decor is so cool!", "Really lovely small pub, 10/10 would recommend for a quick pint. Cool statue of James Joyce outside who used to teach English in the building back yonder.", "Best place to watch Pula‘s life, friendly service, reasonable prices, my recommendation: the Negroni", "A nice cup of coffee on a beautiful spot next to the Arch of the Sergii."], "price": "medium"}}

1. {"type": "fort", "properties": {"name": "Fort Brioni Minor", "tags": ["fortress", "historic", "coastal", "military_history", "national_park", "island", "events"], "description": "Large Austro-Hungarian coastal fortress on Mali Brijun, known for its preserved military architecture, strategic sea-facing position, and summer theatre performances held within the fort.", "rating": 4.8, "reviews": ["We have a chance to enjoy there as part of the King Lear play. Fortress is amasing an perfectly fitted the show.", "Amazing still standing fortress from the beginning of 20th century. Used by Ulysses theatre", "A beautiful place, lots of wonderful things to see, from rich flora and fauna to beautiful historical buildings."]}}
2. {"type": "fort", "properties": {"name": "Utvrda Marie Louise", "tags": ["fortress", "historic", "coastal", "panoramic_view", "military_history"], "description": "Large 19th-century coastal fortress on the Muzil peninsula in Pula, known for its circular design and strategic views over the bay entrance.", "rating": 4.4, "reviews": ["The remains of a large defensive fort on Musil peninsula. It was built in the 19th century and used by different armies throughout history. Today it is almost forgotten but still far from a mere ruin. The strength of its walls and beauty of its architecture are still evident. It is safe to explore, yet watch your step for scrap metal, holes and other obstacles. Just like Verudela this ruin should be restored and put to good use.", "Spectacular abandoned fort. You can explore everything. Be careful.", "There's a good, convenient entrance, but it's guarded. Closed to the curious. However, you can access the area along the western coast along a narrow path. Along the way, you'll encounter abandoned former military fortifications. It's a bit scary! Once inside, I felt like a stalker! I saw several huge peacocks. This was once a huge military base. Now everything is abandoned, but the buildings, both above and below ground, are in excellent condition."]}}
3. {"type": "fort", "properties": {"name": "Fort Bourguignon", "tags": ["fortress", "historic", "coastal", "events", "military_history"], "description": "19th-century coastal fortress in Pula, known for its circular design, military history, and cultural events.", "rating": 4.2, "reviews": ["Beautiful Austro-Hungarian fortress which is preserved, but abandoned. In my opinion the most beautiful one in Pula. Unfortunately it is closed for visitors. I recommend to visit in early morning (between 6:00-7:00 AM) because there are not any people around and sunlight is perfect for photography.", "Very nice place to visit. Not crowdy. 10 minutes slow walk from free parking space on front of resort ( on right side from the main gate). To reach te place we used wide route on right side of resort entrance on the bushes."]}}
4. {"type": "fort", "properties": {"name": "Fort Ovine", "tags": ["fortress", "historic", "military_history", "coastal"], "description": "Abandoned Austro-Hungarian coastal fort in the Valovine area, known for its atmospheric tunnels, overgrown walls, and striking rooftop views over the sea.", "rating": 4.4, "reviews": ["It was a small ruin with an entrance, a hallway, some rooms and a tunnel to a small katacomb. The dark tunnel which looks like the entrance of a katacomb has a slight slope and is slippery. Unfortunately some of the rooms were used as toilets - no understanding for that... The parking lots are kind off in front of fort and very busy. So make shure to plan your visit in the morning.", "Nothing special about this place, I have only visited the exterior though. I don't know if I suggest the visit. There is a civil guard near the entrance", "A fortification overgrown in the rock. Large areas are empty and dark. For those who enjoy extreme sports, this is for you."]}}
5. {"type": "park", "properties": {"name": "Park Monte Zaro", "tags": ["park", "historic", "hilltop", "observatory", "city_center", "family_friendly", "playground"], "description": "Largest historic park in Pula, set on a hill around the observatory, with fountains, Mediterranean trees, and scenic views over the city and harbour.", "rating": 4.5, "reviews": ["I didn’t expect much, but Montezaro Park turned out to be such a nice surprise. It’s quiet, full and perfect when you need a break from the heat and crowds. I grabbed a coffee and just walked around for a bit…. really relaxing spot with a great local feel.", "The roots of Montezaro Park are deeply embedded in Pula’s past. Originally designed in the 19th century, it was a retreat for nobility and a symbol of prestige. Small park that has a fountain, many trails to get around, and plenty of flora areas to enjoy. It's on a small hill so you can get some views of the surrounding area.", "A quiet city park on a hill overlooking Pula harbour, a welcome escape far from the madding crowd."]}}

1. {"type": "beach", "properties": {"name": "Plaža Jupiter", "tags": ["beach", "island", "stone", "paved", "national_park", "family_friendly"], "description": "Well-maintained designated beach on Veli Brijun, known for its stone-paved shore, two spacious terraces, and relaxing atmosphere. It is one of the official swimming areas on the island, appreciated for its cleanliness, safety, and beautiful sunset views.", "rating": 4.1, "reviews": ["Jupiter Beach on Brijuni Island in Croatia is a true paradise! The water is crystal clear and ideal for children to swim and play safely. For snorkeling enthusiasts, this beach is an absolute dream – you can observe countless fish in their natural habitat. A perfect place to enjoy the beauty of the underwater world. Highly recommended!", "Cozy little beach"]}}
2. {"type": "cafe", "properties": {"tags": ["coffee", "cocktails", "beer", "wine", "city_center"], "outdoor_seating": true, "indoor_seating": true, "name": "Caffe Bar Uliks", "phone": "+385 52 219 158", "opening_hours": "Mo-Su 07:00-02:00", "addr:housenumber": "1", "addr:street": "Trg Portarata", "rating": 4.5, "description": "A historic café bar in the very center of Pula, right next to the Arch of the Sergii, known for its literary connection to James Joyce, a wide drinks selection, specialty local spirits and craft beers, and a lively atmosphere with quizzes and other events.", "reviews": ["Would highly recommend! Really nice people inside and great vibes. The decor is so cool!", "Really lovely small pub, 10/10 would recommend for a quick pint. Cool statue of James Joyce outside who used to teach English in the building back yonder.", "Best place to watch Pula‘s life, friendly service, reasonable prices, my recommendation: the Negroni", "A nice cup of coffee on a beautiful spot next to the Arch of the Sergii."], "price": "medium"}}
3. {"type": "cafe", "properties": {"tags": ["coffee", "pub", "beer", "city_center"], "outdoor_seating": true, "indoor_seating": true, "name": "Bounty", "phone": "+385 52 218 088", "opening_hours": "Mo-Su 07:00-23:00", "addr:housenumber": "8", "addr:street": "Veronska", "rating": 4.6, "description": "A cozy Irish-style pub in city center, known for draft beer, a wide drink selection, and a comfortable terrace with a relaxed atmosphere.", "reviews": ["An excellent Irish pub with a great Irish atmosphere. Clean, tidy, good to be here As it is a bit away from the busy tourist area, it is not crowded. Guinness and local beers on tap, plus a great selection of drinks. Shaded, comfortable terrace.", "Didn't get to stay here for long (one drink) however it has a real homely feel to the place and is a really nicely situated pub. Good atmosphere and seating options, good drink choices which are more foreign options (Guinness/Heineken/Jack Daniels etc) and the prices are quite good also! Would recommend stopping in for some drinks if in the local area!", "This is a proper bar. Beautiful inside. A nice seating area outside. They have a really good selection of drinks on offer."], "price": null}}
4. {"type": "sport", "properties": {"name": "Kayak Centar Pula", "tags": ["sports", "kayaking", "coastal", "family_friendly"], "description": "Kayak tours in Pula offer an active way to explore the coastline through paddling, snorkeling, and swimming, with options including island, cliff and cave tours, sunset paddles, morning tours, and kayak rentals for solo visitors, couples, or families.", "rating": 5.0, "reviews": ["We booked this tour via an enquiry through the website but received communication via Whatsapp, which was very helpful. We were able to clarify stuff and gave us confidence to book. Our guide was great, he knew the area well having grown up locally and was friendly and happy to chat with all of the group, as well as imparting his local knowledge. The kayaking route was brilliant, not too strenuous with lots of great views and a break for swimming, snorkelling (snorkel & mask provided) or relaxing. The drinks and snacks provided by the guide was a great touch. The guide also took plenty of 'action' pictures and we all received a link to download the pictures for FOC, great keepsakes. Definitely recommend.", "We had an amazing time on the 3-hour sea kayak excursion with Pula Kayak Centre! Toni, our guide, was fantastic super knowledgeable, friendly, and made the experience feel really personal. The scenery was absolutely stunning, with crystal-clear waters and beautiful coastal views. Toni took us to some hidden spots and made sure we were all comfortable and safe throughout. It was a perfect blend of adventure and relaxation. Highly recommend this tour to anyone looking for an unforgettable experience in Pula!", "Super nice! Really worth! We paid 26 euro for a 2 person Kayak in 2 hours. It was perfect time to explore some islands around Verudela!"]}}
5. {"type": "fort", "properties": {"name": "Battery San Giovanni", "tags": ["fortress", "historic", "coastal", "military_history"], "description": "Historic coastal battery above Verudela in Pula, built as part of the Austro-Hungarian defence system and known for its ramparts, military character, and location near Aquarium Pula and the beaches.", "rating": 4.8, "reviews": ["Very beautifully made and presented. This facility houses the second part of the aquarium, which gathers more exotic animal species and provides a look at the development and power of the Austro-Hungarian Navy. I was enchanted by everything I saw in both facilities. You should definitely visit the Pula Aquarium. It is relaxing, inspiring, enchanting. Highly recommended.", "The second part of the aquarium is located in the Baterija San Giovanni. Tickets must be purchased at the upper level. This section of the aquarium is dedicated to 'exotic' animal species and concludes with a marine exhibit. The aquariums are well worth seeing. Our children were thrilled. Important on hot days... the aquarium is air-conditioned. The conversion of the fort into an aquarium is also very well done. In short: absolutely worth seeing.", "The second part of the aquarium, with the larger animals."]}}

1. {"type": "cafe", "properties": {"tags": ["coffee", "cocktails", "beer", "wine", "city_center"], "outdoor_seating": true, "indoor_seating": true, "name": "Caffe Bar Uliks", "phone": "+385 52 219 158", "opening_hours": "Mo-Su 07:00-02:00", "addr:housenumber": "1", "addr:street": "Trg Portarata", "rating": 4.5, "description": "A historic café bar in the very center of Pula, right next to the Arch of the Sergii, known for its literary connection to James Joyce, a wide drinks selection, specialty local spirits and craft beers, and a lively atmosphere with quizzes and other events.", "reviews": ["Would highly recommend! Really nice people inside and great vibes. The decor is so cool!", "Really lovely small pub, 10/10 would recommend for a quick pint. Cool statue of James Joyce outside who used to teach English in the building back yonder.", "Best place to watch Pula‘s life, friendly service, reasonable prices, my recommendation: the Negroni", "A nice cup of coffee on a beautiful spot next to the Arch of the Sergii."], "price": "medium"}}
2. {"type": "zoo", "properties": {"name": "Fazanerija", "tags": ["zoo", "animals", "family_friendly", "national_park", "island"], "description": "Small animal and bird area where visitors can see peacocks, turkeys, guinea fowl, parrots, and other birds, while the site also serves as a recovery and temporary care center for wild animals.", "rating": 4.1, "reviews": ["Don’t miss seeing this bird! Easy to find, unique experience", "Koji is awesome! He knows a few words, best one being 'tito'", "The animals seem content, and the facility was well-maintained. Of course, the buildings are old, and it's not a large zoo. But it's definitely worth a visit."]}}
3. {"type": "cafe", "properties": {"tags": ["coffee", "wine", "cocktails", "city_center"], "outdoor_seating": true, "indoor_seating": true, "name": "Sirena", "phone": null, "opening_hours": "Mo-Fr 08:00-24:00; Sa-Su 09:00-24:00", "addr:housenumber": "12", "addr:street": "Forum", "rating": 4.1, "description": "A relaxed café on Pula’s main square, offering coffee, wine, cocktails, and terrace seating with views of the historic Forum.", "reviews": ["Wonderful place for coffee or a glass of delicious wine, with a view of the beautiful buildings around Forum Square. During our visits, we had the pleasure to meet waitress with long, slightly wavy hair — she was sooo cool and perfectly handled all orders. We'd love to come back! ❤️", "Nice terrace on the square! During the day, lots of shadow because of the wide parasols! The square is open, don’t get sunburned !", "Nice place, amazing coctails and lovely staff!"], "price": null}}
4. {"type": "museum", "properties": {"name": "Zerostrasse", "tags": ["museum", "historic", "military_history", "city_center", "near_attractions", "family_friendly"], "description": "Underground tunnel complex beneath central Pula, created as a wartime shelter system during the Austro-Hungarian period and today presented as a historic site known as Zerostrasse.", "rating": 4.3, "reviews": ["Nice tunnel system that is easy to navigate. There seems to be very little information about the tunnels themselves and more information about various things that happened in Pula around the area. Tickets to the tunnel gove you access to the fort above.", "Tunnels underneath the citadel with access to the citadel included in the price if you work your way up. I did this in reverse and made my way down through the tunnels. Blissfully cool after the heat of the exterior. Fascinated by the tunnels and side rooms. Would have liked to see more information provided on their wartime use, and not just learn about the trams. Found a lovely piece of art painted onto a wall in one of the side rooms, left there by a previous resident who had tried to bring a little of the outside indoors perhaps? A little forgotten masterpiece just waiting to be discovered. Just kind of stumbled across it as I explored, but maybe should have been signposted with a bit of context provided. The tunnels exit at locations in the old town. As a tourist myself this left me almost instantly in the shopping area at the end of my visit. I am sure not the original builders intention, but very welcome for someone like myself trying to get the most out of their day.", "Fascinating underground tunnels. Zerostrasse is a network of WWI-era tunnels beneath Pula, originally built as shelters. It’s a cool and quiet escape from the summer heat, with interesting historical displays along the way. Not a long visit, but definitely worth it if you're curious about the city's wartime past."]}}
5. {"type": "attraction", "properties": {"name": "kayak tours | pulsevents.hr", "tags": ["attraction", "kayaking", "coastal"], "description": "Guided kayak adventure in Pula offering coastal exploration, sea caves, snorkeling, and scenic views of the city’s rocky shoreline, suitable for both beginners and experienced paddlers.", "rating": 4.8, "reviews": ["It was an amazing experience with plenty of challenging activities included: kayaking, snorkeling, cliff jumping, passing through canals within the rocks. The monitors are super friendly, speakgood English and take good care of the group. It is easily doable with kids at the age of 7 and 13 in a three place kayak. The monitors made plenty of underwater photos of all member of the group with good quality cameras. Water or beers were provided at the bay when we stopped, just like the swimming Google's for snorkeling. Highly recommended.", "This was truly one of the best experiences of my life!! Jhonnes was an excellent guide who did everything he could to make it a great trip. He is also amazing at capturing picturesque moments. My family and friends that saw the pictures were in aww and asked who the photographer was. I would highly recommend this adventure to anyone considering it.", "A fantastic experience from start to finish. Well organised and very patient with us as inexperienced kayakers. We were kept updated and when our taxi left us in the wrong place a quick phonecall to them and they sorted everything to get us there on time. First class service, we were with teenagers who loved it too. Thank you"]}}

1. {"type": "museum", "properties": {"name": "Zerostrasse", "tags": ["museum", "historic", "military_history", "city_center", "near_attractions", "family_friendly"], "description": "Underground tunnel complex beneath central Pula, created as a wartime shelter system during the Austro-Hungarian period and today presented as a historic site known as Zerostrasse.", "rating": 4.3, "reviews": ["Nice tunnel system that is easy to navigate. There seems to be very little information about the tunnels themselves and more information about various things that happened in Pula around the area. Tickets to the tunnel gove you access to the fort above.", "Tunnels underneath the citadel with access to the citadel included in the price if you work your way up. I did this in reverse and made my way down through the tunnels. Blissfully cool after the heat of the exterior. Fascinated by the tunnels and side rooms. Would have liked to see more information provided on their wartime use, and not just learn about the trams. Found a lovely piece of art painted onto a wall in one of the side rooms, left there by a previous resident who had tried to bring a little of the outside indoors perhaps? A little forgotten masterpiece just waiting to be discovered. Just kind of stumbled across it as I explored, but maybe should have been signposted with a bit of context provided. The tunnels exit at locations in the old town. As a tourist myself this left me almost instantly in the shopping area at the end of my visit. I am sure not the original builders intention, but very welcome for someone like myself trying to get the most out of their day.", "Fascinating underground tunnels. Zerostrasse is a network of WWI-era tunnels beneath Pula, originally built as shelters. It’s a cool and quiet escape from the summer heat, with interesting historical displays along the way. Not a long visit, but definitely worth it if you're curious about the city's wartime past."]}}
2. {"type": "fort", "properties": {"name": "Utvrda San Michele", "tags": ["fortress", "historic", "hilltop", "military_history", "closed_area", "city_center"], "description": "Historic horseshoe-shaped fortress on the San Michele hill in Pula, built as part of the city’s defence system and known for its preserved military architecture and long later use within the hospital complex.", "rating": 4.3, "reviews": ["One of many fortresses located in Pula, and I would say one of my favorites, sadly no one maintains them and they are falling apart. This is beautiful city with rich history and so many potetial and 0 will to restore them... who knows, maybe one day the people who manage the city will get into their heads that Pula is not only the sea and the Arena... Pula is much more...", "It could be an attraction if it wasn't completely neglected."]}}
3. {"type": "fort", "properties": {"name": "Battery San Giovanni", "tags": ["fortress", "historic", "coastal", "military_history"], "description": "Historic coastal battery above Verudela in Pula, built as part of the Austro-Hungarian defence system and known for its ramparts, military character, and location near Aquarium Pula and the beaches.", "rating": 4.8, "reviews": ["Very beautifully made and presented. This facility houses the second part of the aquarium, which gathers more exotic animal species and provides a look at the development and power of the Austro-Hungarian Navy. I was enchanted by everything I saw in both facilities. You should definitely visit the Pula Aquarium. It is relaxing, inspiring, enchanting. Highly recommended.", "The second part of the aquarium is located in the Baterija San Giovanni. Tickets must be purchased at the upper level. This section of the aquarium is dedicated to 'exotic' animal species and concludes with a marine exhibit. The aquariums are well worth seeing. Our children were thrilled. Important on hot days... the aquarium is air-conditioned. The conversion of the fort into an aquarium is also very well done. In short: absolutely worth seeing.", "The second part of the aquarium, with the larger animals."]}}
4. {"type": "fort", "properties": {"name": "Mletačka utvrda", "tags": ["fortress", "historic", "panoramic_view", "city_center", "events", "concerts"], "description": "French-style defensive fortress built by the Venetians in the 1600s, with views of the city & bay.", "rating": 4.5, "reviews": ["Amazing views from the top - panoramic of the whole site - was helpful as my first look of the city to get my bearings. Loved that the ticket also included use of the undercity tunnel network - helpful as it was raining on and off (visited a couple of days ago!)", "Very beautiful views. Nice fortress, with a tower from where the views are even more wonderful. The entrance fee is 7 euros.", "I like history and I've been to quite a few other fortresses and the design follows other fortress designs because you're trying to defend and required similar designs and systems. The fortress has been disarmed and the museums/displays on site are bright with information and displays but I found some lack.....that is not a bad comment, just a minor con. There has obviously been a lot of work to maintain the integrity of the stone work and that is definitely a pro. Definitely worth the time for a visit. I rate this 4 stars."]}}
5. {"type": "fort", "properties": {"name": "Fort Brioni Minor", "tags": ["fortress", "historic", "coastal", "military_history", "national_park", "island", "events"], "description": "Large Austro-Hungarian coastal fortress on Mali Brijun, known for its preserved military architecture, strategic sea-facing position, and summer theatre performances held within the fort.", "rating": 4.8, "reviews": ["We have a chance to enjoy there as part of the King Lear play. Fortress is amasing an perfectly fitted the show.", "Amazing still standing fortress from the beginning of 20th century. Used by Ulysses theatre", "A beautiful place, lots of wonderful things to see, from rich flora and fauna to beautiful historical buildings."]}}

1. {"type": "cafe", "properties": {"tags": ["coffee", "wine", "cocktails", "city_center"], "outdoor_seating": true, "indoor_seating": true, "name": "Sirena", "phone": null, "opening_hours": "Mo-Fr 08:00-24:00; Sa-Su 09:00-24:00", "addr:housenumber": "12", "addr:street": "Forum", "rating": 4.1, "description": "A relaxed café on Pula’s main square, offering coffee, wine, cocktails, and terrace seating with views of the historic Forum.", "reviews": ["Wonderful place for coffee or a glass of delicious wine, with a view of the beautiful buildings around Forum Square. During our visits, we had the pleasure to meet waitress with long, slightly wavy hair — she was sooo cool and perfectly handled all orders. We'd love to come back! ❤️", "Nice terrace on the square! During the day, lots of shadow because of the wide parasols! The square is open, don’t get sunburned !", "Nice place, amazing coctails and lovely staff!"], "price": null}}
2. {"type": "cafe", "properties": {"tags": ["coffee", "desserts", "sandwiches", "cocktails"], "outdoor_seating": true, "indoor_seating": true, "name": "Leggiero", "phone": "+385 52 634 385", "opening_hours": "Mo-Sa 08:00-21:00; Su 08:00-15:00", "addr:housenumber": "101", "addr:street": "Ulica Rimske Centurijacije", "rating": 3.4, "description": "A modern coffee bar and snack spot in Pula City Mall, offering quality coffee, fresh juices, sandwiches, cakes and sweet treats, ideal for a relaxed coffee break while shopping.", "reviews": ["Very expensive place to drink a coffe! Really too much! A price of a coffee in a supermarket must be more cheaper than one in the centre of the city…excessively!!!", "A very relaxing place whether you sit inside or outside on the terrace, with an excellent selection of food and drinks and outstanding, dedicated staff—especially the waiter Dylan, who is very fast, helpful, friendly, and fully committed to guests at all times, regardless of the crowd and high turnover of people!", "The coffee is average, but definitely not worth €2.90. I’ve had much better coffee for less money. Judging by other reviews, I’m clearly not the only one who thinks the quality doesn’t justify the price.", "Always smiling, helpful, and quick, even when dealing with guests who can be very rude and impatient. Kudos to them for their patience—they truly make an effort and give their best to do the job as well as possible. Highly recommended!"], "price": "high"}}
3. {"type": "cafe", "properties": {"tags": ["coffee", "cocktails", "desserts", "ice_cream"], "outdoor_seating": true, "indoor_seating": true, "name": "Barbados", "phone": "+385 99 349 0555", "opening_hours": "Mo-Sa 07:30-22:00; Su 07:30-15:00", "addr:housenumber": "14A", "addr:street": "Stoja", "rating": 4.1, "description": "A relaxed cafe in Max City shopping center, ideal for short breaks, long coffee sessions, and casual meetups. With a sunny terrace and laid-back atmosphere, it is a nice place to enjoy coffee, drinks, or a quiet moment with a book or newspaper.", "reviews": ["Great spot for coffee, they also have a fantastic cake selection, I like to come here every time I'm at the mall. The staff is very kind, especially the young female waiter and the young male waiter, both so so kind. I reccomand this spot to anyone passing through, by far the best coffee in the mall", "Great service. Katarina was very helpful and kind. 5/5", "They have real milkshakes made with any flavor ice cream they have! Wonderful"], "price": "medium"}}
4. {"type": "cafe", "properties": {"tags": ["coffee", "cocktails", "city_center"], "outdoor_seating": true, "indoor_seating": true, "name": "Hum", "phone": "+385 97 774 5221", "opening_hours": "Mo-Fr 07:00-15:00; Sa 07:00-14:00; Su 07:00-13:00", "addr:housenumber": "4", "addr:street": "Fontička", "rating": 4.7, "description": "A family-run cafe in the city center, popular for morning coffee and casual drinks.", "reviews": ["Best coffee we had in Pula and our trip in Croatia! Decaf coffee was also excellent. We went every morning of our stay after breakfast. The service was really good too. The two men servers were very kind and by the 3rd day knew our order and asked if we wanted our usual! Highly recommend!", "Great spot for a quick coffee, and it was not a bad one which is great. Normal price, quick service and lots of spots to seat. Yes to this place.", "Sat down and had coffee after visiting the market nearby. Clean toilets, good coffee (also decaf options), friendly service! The shaded terrace helped with the heat 😊."], "price": "medium"}}
5. {"type": "cafe", "properties": {"tags": ["coffee", "smoothies", "healthy", "brunch", "breakfast", "international", "vegan", "vegetarian", "gluten_free"], "outdoor_seating": true, "indoor_seating": true, "name": "Kavana Lattiera", "phone": "+385 91 537 4711", "opening_hours": "Mo-Fr 08:00-16:00; Sa-Su 09:00-15:00", "addr:housenumber": "4", "addr:street": "Trg Kralja Tomislava", "rating": 4.8, "description": "A modern cafe in Veruda known for specialty coffee, healthy breakfasts, smoothie bowls, homemade cakes, and a relaxed neighborhood atmosphere. Inspired by Berlin-style coffee culture, it is a popular spot for morning coffee, brunch, fresh juices, and casual meetups on the square.", "reviews": ["We stopped at Kavana Lattiera and really enjoyed the atmosphere. The coffee and desserts were excellent, and the place has a very nice vibe for sitting down and relaxing. One thing that stood out, though, was the wait time – we had to wait more than 30 minutes for our order, and it felt like we had been forgotten for a while. Once everything finally arrived, the quality made up for it, but the service could definitely be more attentive.", "Great place with a fresh and healthy offer! The menu is full of delicious options made from quality ingredients — from smoothie bowls and sandwiches to great breakfast choices. The açaí bowl is especially tasty and definitely worth trying. Perfect spot for a relaxed coffee or a healthy meal.", "During the vacation with my girlfriend (who only eats vegetarian and gluten free) in Croatia, we went a couple of times here. What a nice place and so many locals went there as well. The menu was only on Croatian and we had to translate but that was not a problem at all. The service, the food, everything is so nice here. And the best thing is, it’s open until 4 pm.", "Very interesting establishment set amongst apartments and shops. Inside it's a whole different feel to the outside and to what I have seen in Pula, which is very comforting and reminds me of other international cafes, and those special couple of cafes in Zagreb too. The food is so good, healthy and very thoughtful recipes. Veg will be happy. Oat milk available."], "price": "medium"}}

1. {"type": "cafe", "properties": {"tags": ["coffee", "cocktails", "beer", "wine", "city_center"], "outdoor_seating": true, "indoor_seating": true, "name": "Caffe Bar Uliks", "phone": "+385 52 219 158", "opening_hours": "Mo-Su 07:00-02:00", "addr:housenumber": "1", "addr:street": "Trg Portarata", "rating": 4.5, "description": "A historic café bar in the very center of Pula, right next to the Arch of the Sergii, known for its literary connection to James Joyce, a wide drinks selection, specialty local spirits and craft beers, and a lively atmosphere with quizzes and other events.", "reviews": ["Would highly recommend! Really nice people inside and great vibes. The decor is so cool!", "Really lovely small pub, 10/10 would recommend for a quick pint. Cool statue of James Joyce outside who used to teach English in the building back yonder.", "Best place to watch Pula‘s life, friendly service, reasonable prices, my recommendation: the Negroni", "A nice cup of coffee on a beautiful spot next to the Arch of the Sergii."], "price": "medium"}}
2. {"type": "artwork", "properties": {"name": "James Joyce", "tags": ["artwork", "statue", "historic", "city_center", "landmark", "near_attractions"], "description": "Bronze statue of James Joyce in central Pula near the Arch of the Sergii, commemorating the famous Irish writer’s stay in the city and its place in his early literary life.", "rating": 4.7, "reviews": ["This statue made we search more about this Irish novelist. He was an important writer whose books are read today. Here you can take selfies with the statue and enjoy a cup of coffee in a table next to the statue.", "Nice sculpture. Beside a restaurant. If not known, or checked carefully, one can miss it for a person waiting outside a restaurant.", "Nice statue. You can sit with him."]}}
3. {"type": "pub", "properties": {"tags": ["coffee", "cocktails", "beer", "nightlife", "city_center"], "outdoor_seating": true, "indoor_seating": true, "name": "Old City Bar", "phone": "+385 52 222 944", "opening_hours": "Mo-Fr 06:30-02:30; Sa 07:00-02:00; Su 08:30-2:30", "addr:housenumber": "1", "addr:street": "Danteov trg", "rating": 4.5, "description": "A pub located in the center of Pula, offering a relaxed atmosphere during the day and lively parties at night. It is a popular spot for drinks, socializing, and weekend nightlife.", "reviews": ["Great service, Marcus was attentive and funny and made our night!! Drinks were all very good and really enjoyed the theatrics of the different shots and cocktails.", "Best Cocktails in town and super cool service personal, Marcus is our man! Come here! ✨🙌", "The service in this place cannot be compared to anything I've experienced so far of my nine days in Croatia. Not the cheapest, but the persistence and effort by Marco is why you pay a premium. The live music was also quite good. Awsome Bloody Mary if you're into that, and a selection of craft beer if that is your thing. (To Marco's employer, you should give this man a raise)"], "price": "medium"}}
4. {"type": "zoo", "properties": {"name": "Fazanerija", "tags": ["zoo", "animals", "family_friendly", "national_park", "island"], "description": "Small animal and bird area where visitors can see peacocks, turkeys, guinea fowl, parrots, and other birds, while the site also serves as a recovery and temporary care center for wild animals.", "rating": 4.1, "reviews": ["Don’t miss seeing this bird! Easy to find, unique experience", "Koji is awesome! He knows a few words, best one being 'tito'", "The animals seem content, and the facility was well-maintained. Of course, the buildings are old, and it's not a large zoo. But it's definitely worth a visit."]}}
5. {"type": "cafe", "properties": {"tags": ["international", "pancakes", "waffles", "vegetarian"], "outdoor_seating": false, "indoor_seating": true, "name": "Pulačinka", "phone": "+385 52 825 825", "opening_hours": "Mo-Tu 14:00-22:00; We-Su 10:00-23:00", "addr:housenumber": "5", "addr:street": "Istarska", "rating": 4.6, "description": "A cozy dessert and pancake cafe in the center of Pula, known for sweet and savory pancakes, waffles, churros, and other treats. Guests can customize their own pancake with a wide range of spreads, toppings, fruit, biscuits, and chocolate bars, making it a popular spot for breakfast, dessert, or a casual snack.", "reviews": ["We had very tasty dessert here, a giant pancake and a wafle. Both were packed with sweet things full of calories 😀 You can select from pre-set variations of sweet or salty pancakes, or you can create your own version.", "This creperie is absolutely amazing! The pistachio sauce is the best I’ve ever had – rich, creamy, and full of flavor. On top of that, the staff are incredibly friendly and attentive, which makes the whole experience even better. Highly recommended!", "We have tried churros and custom pancake. Churros were good, but not the best that we had. But pancake was almost perfect. It was done quickly without saving on ingredients. There are many different ingredients to choose from and you can mix as much as you want. Prices are high but it is normal for Pula I guess..", "I've eaten here a palačinka with my girlfriend and it was the most Nutella I ate in a long time. Then, she had a blood sugar spike so powerful she drove 360 km without any pause. Recommended before long road trips 👍🏻"], "price": "medium"}}

1. {"type": "cafe", "properties": {"tags": ["coffee", "desserts", "sandwiches", "cocktails"], "outdoor_seating": true, "indoor_seating": true, "name": "Leggiero", "phone": "+385 52 634 385", "opening_hours": "Mo-Sa 08:00-21:00; Su 08:00-15:00", "addr:housenumber": "101", "addr:street": "Ulica Rimske Centurijacije", "rating": 3.4, "description": "A modern coffee bar and snack spot in Pula City Mall, offering quality coffee, fresh juices, sandwiches, cakes and sweet treats, ideal for a relaxed coffee break while shopping.", "reviews": ["Very expensive place to drink a coffe! Really too much! A price of a coffee in a supermarket must be more cheaper than one in the centre of the city…excessively!!!", "A very relaxing place whether you sit inside or outside on the terrace, with an excellent selection of food and drinks and outstanding, dedicated staff—especially the waiter Dylan, who is very fast, helpful, friendly, and fully committed to guests at all times, regardless of the crowd and high turnover of people!", "The coffee is average, but definitely not worth €2.90. I’ve had much better coffee for less money. Judging by other reviews, I’m clearly not the only one who thinks the quality doesn’t justify the price.", "Always smiling, helpful, and quick, even when dealing with guests who can be very rude and impatient. Kudos to them for their patience—they truly make an effort and give their best to do the job as well as possible. Highly recommended!"], "price": "high"}}
2. {"type": "beach", "properties": {"name": "Ambrela Beach", "tags": ["beach", "pebble", "crowdy", "family_friendly"], "description": "Popular pebble beach on Verudela in Pula, known for its shallow sea access, family-friendly setting, nearby parking, and a wide range of beach facilities and water activities.", "rating": 4.3, "reviews": ["It was crowded, even though we were here after rain. It gets deep quickly, there were thousands of small jellyfish in the water, it was strange at first, but you get used to it. We were able to park for free at ARTPARK, although it is difficult to find a free space. Nice, clean beach, there is a side beach, showers are free.", "Clean water, pebble beach. But very crowded in summer.", "A gorgeous beach. The surrounding area is beautiful and clean. There's a couple of meters of sandy entry into the water. Otherwise, there are rocks all around, so protect your feet!", "A very nice beach. Crystal-clear water. Not cold. A food and drink stand. Restrooms. Everything you need for a day out."]}}
3. {"type": "beach", "properties": {"name": "Havajska", "tags": ["beach", "pebble", "crowdy"], "description": "Tiny pebble beach surrounded by cliffs & accessible by carved staircase, known for its strong waves.", "rating": 4.4, "reviews": ["Excellent free beach near Pula. We went there the last week of August, arriving around 10:00 AM. The main reef was crowded, but there were still some shaded spots available. A good spot to dive into the blue water and relax. Bring your own gear, as it's free and there are no services nearby. The water is clear, with some small fish but also many transparent jellyfish. Free parking is about a 10-minute walk away.", "The beach is beautifully located, but unfortunately very crowded. Due to the nearby hotel complexes and the popularity of the place, there are a lot of people on the beach. There are also many jellyfish there. It is purely a rocky and pebble beach, so a sleeping mat or similar may be useful for lying down.", "Great beach here, very secluded and has it's own privacy! Beach is rocky of course, but one of the better ones and very clear. Can have a great swim here. Easy to get up and down from the beach via the stairs. Shady areas to the sides."]}}
4. {"type": "cafe", "properties": {"tags": ["balkan", "coffee", "beer", "city_center"], "outdoor_seating": false, "indoor_seating": true, "name": "Caffe Bar AS", "phone": null, "opening_hours": null, "addr:housenumber": "39", "addr:street": "Nikole Tesle", "rating": 4.3, "description": "A local neighborhood bar just above the Arena area in central Pula, known for a casual atmosphere, coffee, beer, and everyday drinks in a simple, social setting.", "reviews": ["A simple small one room locals bar not far from the rear of the arena. A lot nicer inside than the exterior would have you believe. Very reasonable prices. Paulicarus asked for a small Ožujsko. 2.3€ for a 0.33l bottle. Nice and cold. The 0.5l is only 30 cents more but need to drink fast to enjoy it cold. A pleasant bar for a quick beer.", "A great local bar in the back streets of Pula. I like it here away from the tourist areas 👍", "Beautiful bar, where I met new friends and the drinks are cheap. I love it!"], "price": "low"}}
5. {"type": "cafe", "properties": {"tags": ["coffee", "ice_cream", "cocktails", "vegan", "city_center"], "outdoor_seating": true, "indoor_seating": true, "name": "Giardino Bar", "phone": "+385 99 403 4680", "opening_hours": "Mo-Fr 07:00-24:00; Sa 07:00-01:00; Su off", "addr:housenumber": "3", "addr:street": "Giardini", "rating": 4.7, "description": "A cozy café in the center of Pula, ideal for coffee, ice cream, drinks, and a relaxing break.", "reviews": ["Nice place, great drink (teragino), the music wasn't loud, so it wasn't a problem to hear each other. And we got free chips and nuts with the drink.", "Great location and atmosphere and an extremely polite and helpful waiter, a real refreshment!", "Good music, delicious coffee, even a vegan milk option, and clean bathrooms."], "price": "low"}}

1. {"type": "cafe", "properties": {"tags": ["coffee", "cocktails", "beer", "wine", "city_center"], "outdoor_seating": true, "indoor_seating": true, "name": "Caffe Bar Uliks", "phone": "+385 52 219 158", "opening_hours": "Mo-Su 07:00-02:00", "addr:housenumber": "1", "addr:street": "Trg Portarata", "rating": 4.5, "description": "A historic café bar in the very center of Pula, right next to the Arch of the Sergii, known for its literary connection to James Joyce, a wide drinks selection, specialty local spirits and craft beers, and a lively atmosphere with quizzes and other events.", "reviews": ["Would highly recommend! Really nice people inside and great vibes. The decor is so cool!", "Really lovely small pub, 10/10 would recommend for a quick pint. Cool statue of James Joyce outside who used to teach English in the building back yonder.", "Best place to watch Pula‘s life, friendly service, reasonable prices, my recommendation: the Negroni", "A nice cup of coffee on a beautiful spot next to the Arch of the Sergii."], "price": "medium"}}
2. {"type": "marina", "properties": {"name": "ACI Marina Pula", "tags": ["marina", "city_center", "restaurant", "near_attractions"], "description": "City marina in the heart of Pula, known for its protected harbour setting, full nautical services, boat rentals, and unique views of the Roman Arena.", "rating": 4.3, "reviews": ["ACI Marina in Pula is a top-notch spot for boaters and visitors alike. Well-maintained docks, friendly staff, and beautiful views make it perfect for sailing, relaxing by the water, or enjoying nearby cafes and restaurants.", "Very good Marina restaurant, helpful and friendly Marinero. Clean sanitary facilities, in the middle of the city. Can be noisy sometimes. Marina ist best contacted if you are already quite near if via VHF. Mobile phone is also possible.", "The marina is nice and spacious. You can walk above the coast and admire the boats and views."]}}
3. {"type": "cafe", "properties": {"tags": ["mediterranean", "coffee", "gallery", "cocktails", "ice_cream", "desserts", "city_center"], "outdoor_seating": true, "indoor_seating": true, "name": "Cvajner", "phone": "+385 52 216 502", "opening_hours": "Mo-Sa 08:00-23:00; Su 10:00-23:00", "addr:housenumber": "2", "addr:street": "Forum", "rating": 4.3, "description": "Art café and gallery on Pula’s main square, known for its striking historic interior, artistic atmosphere, and terrace overlooking the Forum and the Temple of Augustus.", "reviews": ["Great place to get some coffee and quick food; located right in Forum Square, so finding this place is super simple. Service could be a bit better and more organized, but otherwise everything was super tasty.", "Very nice iced coffee. Cozy enviroment, interesting design with restored paintings on the walls.", "This is in a great location if you sit outside. The Forum has a great buzz and is beautiful. Prices are quite reasonable for such a location (big draught beer €4.2) Most of the staff are busy and seem a bit a bit grumpy ( except one nice waitress) There are small menus on the tables and bills are clearly itemised. We saw a family leave after waiting ages to be served. Inside looks nice too with some old frescos. Locals here too. Worth a visit though.", "Gorgeous and cosy caffe... Well preserved historical charm done by keeping the original tapestry and blending it in with the new one. Drinks are well made and the staff is polite, very nice place to come to on a rainy day."], "price": "medium"}}
4. {"type": "hostel", "properties": {"name": "Sol Garden - Hostel with a Soul", "tags": ["hostel", "near_attractions"], "description": "A simple and budget-friendly stay close to Pula Arena and the city’s historic center, offering dormitories and twin rooms with access to shared bathrooms. Guests can use a fully equipped shared kitchen, relax in the garden or on the terrace, and easily reach the waterfront, restaurants, bars and main transport connections on foot.", "rating": 5.0, "reviews": ["The hostel was very clean, it had a pleasant smell, and it was very quiet. It has a large kitchen and a spacious balcony. In the rooms, there are also small lockers that can be locked using the card provided by the reception to access the doors. Nearby, there are 2–3 markets, a coffee bar, and it is also close to the Arena as well as the bus station.", "The hostel is very good, quiet, and has several places nearby such as markets, coffee bars, and other shops. It also has a nice balcony, a large kitchen, and spacious bathrooms. The rooms are clean, air-conditioned, and everything is in order.", "Location and Staff! Excellent environment"]}}
5. {"type": "cafe", "properties": {"tags": ["wine", "cocktails", "beer", "breakfast", "brunch", "sandwiches", "desserts", "ice_cream", "city_center"], "outdoor_seating": true, "indoor_seating": true, "name": "Enoteca Istriana", "phone": "+385 99 323 6541", "opening_hours": "Mo-Su 09:00-21:00", "addr:housenumber": "11", "addr:street": "Forum", "rating": 3.6, "description": "A wine and coffee bar in the heart of Pula’s old town, right on Forum square by the Temple of Augustus, known for its wide selection of Istrian wines and craft beers.", "reviews": ["Visited this wine bar 4 times during our stay in Pula for coffee, wine, ice cream and sandwiches in a relaxed warm friendly atmosphere. The service was fast and efficient provided by staff who were friendly and accommodating. I highly recommend this wine bar will revisit on a return to Pula.", "Very good place for coffee and verry kind staff. Breakfast is good , this is the best place of the square!"], "price": null}}

1. {"type": "cafe", "properties": {"tags": ["coffee", "cocktails", "beer", "wine", "city_center"], "outdoor_seating": true, "indoor_seating": true, "name": "Caffe Bar Uliks", "phone": "+385 52 219 158", "opening_hours": "Mo-Su 07:00-02:00", "addr:housenumber": "1", "addr:street": "Trg Portarata", "rating": 4.5, "description": "A historic café bar in the very center of Pula, right next to the Arch of the Sergii, known for its literary connection to James Joyce, a wide drinks selection, specialty local spirits and craft beers, and a lively atmosphere with quizzes and other events.", "reviews": ["Would highly recommend! Really nice people inside and great vibes. The decor is so cool!", "Really lovely small pub, 10/10 would recommend for a quick pint. Cool statue of James Joyce outside who used to teach English in the building back yonder.", "Best place to watch Pula‘s life, friendly service, reasonable prices, my recommendation: the Negroni", "A nice cup of coffee on a beautiful spot next to the Arch of the Sergii."], "price": "medium"}}
2. {"type": "cafe", "properties": {"tags": ["coffee", "wine", "cocktails", "city_center"], "outdoor_seating": true, "indoor_seating": true, "name": "Sirena", "phone": null, "opening_hours": "Mo-Fr 08:00-24:00; Sa-Su 09:00-24:00", "addr:housenumber": "12", "addr:street": "Forum", "rating": 4.1, "description": "A relaxed café on Pula’s main square, offering coffee, wine, cocktails, and terrace seating with views of the historic Forum.", "reviews": ["Wonderful place for coffee or a glass of delicious wine, with a view of the beautiful buildings around Forum Square. During our visits, we had the pleasure to meet waitress with long, slightly wavy hair — she was sooo cool and perfectly handled all orders. We'd love to come back! ❤️", "Nice terrace on the square! During the day, lots of shadow because of the wide parasols! The square is open, don’t get sunburned !", "Nice place, amazing coctails and lovely staff!"], "price": null}}
3. {"type": "cafe", "properties": {"tags": ["coffee", "pub", "beer", "city_center"], "outdoor_seating": true, "indoor_seating": true, "name": "Bounty", "phone": "+385 52 218 088", "opening_hours": "Mo-Su 07:00-23:00", "addr:housenumber": "8", "addr:street": "Veronska", "rating": 4.6, "description": "A cozy Irish-style pub in city center, known for draft beer, a wide drink selection, and a comfortable terrace with a relaxed atmosphere.", "reviews": ["An excellent Irish pub with a great Irish atmosphere. Clean, tidy, good to be here As it is a bit away from the busy tourist area, it is not crowded. Guinness and local beers on tap, plus a great selection of drinks. Shaded, comfortable terrace.", "Didn't get to stay here for long (one drink) however it has a real homely feel to the place and is a really nicely situated pub. Good atmosphere and seating options, good drink choices which are more foreign options (Guinness/Heineken/Jack Daniels etc) and the prices are quite good also! Would recommend stopping in for some drinks if in the local area!", "This is a proper bar. Beautiful inside. A nice seating area outside. They have a really good selection of drinks on offer."], "price": null}}
4. {"type": "memorial", "properties": {"name": "Lino Mariani", "tags": ["bust", "memorial", "historic", "city_center", "near_attractions"], "description": "A bronze memorial bust dedicated to an antifascist partisan, trade unionist and worker remembered for his role in the turbulent post-war history of Pula. Placed near the ancient city walls and Hercules Gate, it adds a modern historical layer to this Roman setting and commemorates local resistance, labour struggle and civic memory.", "rating": 4.5, "reviews": null}}
5. {"type": "fort", "properties": {"name": "Fort Brioni Minor", "tags": ["fortress", "historic", "coastal", "military_history", "national_park", "island", "events"], "description": "Large Austro-Hungarian coastal fortress on Mali Brijun, known for its preserved military architecture, strategic sea-facing position, and summer theatre performances held within the fort.", "rating": 4.8, "reviews": ["We have a chance to enjoy there as part of the King Lear play. Fortress is amasing an perfectly fitted the show.", "Amazing still standing fortress from the beginning of 20th century. Used by Ulysses theatre", "A beautiful place, lots of wonderful things to see, from rich flora and fauna to beautiful historical buildings."]}}

1. {"type": "beach", "properties": {"name": "Plaža Jupiter", "tags": ["beach", "island", "stone", "paved", "national_park", "family_friendly"], "description": "Well-maintained designated beach on Veli Brijun, known for its stone-paved shore, two spacious terraces, and relaxing atmosphere. It is one of the official swimming areas on the island, appreciated for its cleanliness, safety, and beautiful sunset views.", "rating": 4.1, "reviews": ["Jupiter Beach on Brijuni Island in Croatia is a true paradise! The water is crystal clear and ideal for children to swim and play safely. For snorkeling enthusiasts, this beach is an absolute dream – you can observe countless fish in their natural habitat. A perfect place to enjoy the beauty of the underwater world. Highly recommended!", "Cozy little beach"]}}
2. {"type": "cafe", "properties": {"tags": ["coffee", "cocktails", "beer", "wine", "city_center"], "outdoor_seating": true, "indoor_seating": true, "name": "Caffe Bar Uliks", "phone": "+385 52 219 158", "opening_hours": "Mo-Su 07:00-02:00", "addr:housenumber": "1", "addr:street": "Trg Portarata", "rating": 4.5, "description": "A historic café bar in the very center of Pula, right next to the Arch of the Sergii, known for its literary connection to James Joyce, a wide drinks selection, specialty local spirits and craft beers, and a lively atmosphere with quizzes and other events.", "reviews": ["Would highly recommend! Really nice people inside and great vibes. The decor is so cool!", "Really lovely small pub, 10/10 would recommend for a quick pint. Cool statue of James Joyce outside who used to teach English in the building back yonder.", "Best place to watch Pula‘s life, friendly service, reasonable prices, my recommendation: the Negroni", "A nice cup of coffee on a beautiful spot next to the Arch of the Sergii."], "price": "medium"}}
3. {"type": "cafe", "properties": {"tags": ["coffee", "pub", "beer", "city_center"], "outdoor_seating": true, "indoor_seating": true, "name": "Bounty", "phone": "+385 52 218 088", "opening_hours": "Mo-Su 07:00-23:00", "addr:housenumber": "8", "addr:street": "Veronska", "rating": 4.6, "description": "A cozy Irish-style pub in city center, known for draft beer, a wide drink selection, and a comfortable terrace with a relaxed atmosphere.", "reviews": ["An excellent Irish pub with a great Irish atmosphere. Clean, tidy, good to be here As it is a bit away from the busy tourist area, it is not crowded. Guinness and local beers on tap, plus a great selection of drinks. Shaded, comfortable terrace.", "Didn't get to stay here for long (one drink) however it has a real homely feel to the place and is a really nicely situated pub. Good atmosphere and seating options, good drink choices which are more foreign options (Guinness/Heineken/Jack Daniels etc) and the prices are quite good also! Would recommend stopping in for some drinks if in the local area!", "This is a proper bar. Beautiful inside. A nice seating area outside. They have a really good selection of drinks on offer."], "price": null}}
4. {"type": "sport", "properties": {"name": "Kayak Centar Pula", "tags": ["sports", "kayaking", "coastal", "family_friendly"], "description": "Kayak tours in Pula offer an active way to explore the coastline through paddling, snorkeling, and swimming, with options including island, cliff and cave tours, sunset paddles, morning tours, and kayak rentals for solo visitors, couples, or families.", "rating": 5.0, "reviews": ["We booked this tour via an enquiry through the website but received communication via Whatsapp, which was very helpful. We were able to clarify stuff and gave us confidence to book. Our guide was great, he knew the area well having grown up locally and was friendly and happy to chat with all of the group, as well as imparting his local knowledge. The kayaking route was brilliant, not too strenuous with lots of great views and a break for swimming, snorkelling (snorkel & mask provided) or relaxing. The drinks and snacks provided by the guide was a great touch. The guide also took plenty of 'action' pictures and we all received a link to download the pictures for FOC, great keepsakes. Definitely recommend.", "We had an amazing time on the 3-hour sea kayak excursion with Pula Kayak Centre! Toni, our guide, was fantastic super knowledgeable, friendly, and made the experience feel really personal. The scenery was absolutely stunning, with crystal-clear waters and beautiful coastal views. Toni took us to some hidden spots and made sure we were all comfortable and safe throughout. It was a perfect blend of adventure and relaxation. Highly recommend this tour to anyone looking for an unforgettable experience in Pula!", "Super nice! Really worth! We paid 26 euro for a 2 person Kayak in 2 hours. It was perfect time to explore some islands around Verudela!"]}}
5. {"type": "fort", "properties": {"name": "Battery San Giovanni", "tags": ["fortress", "historic", "coastal", "military_history"], "description": "Historic coastal battery above Verudela in Pula, built as part of the Austro-Hungarian defence system and known for its ramparts, military character, and location near Aquarium Pula and the beaches.", "rating": 4.8, "reviews": ["Very beautifully made and presented. This facility houses the second part of the aquarium, which gathers more exotic animal species and provides a look at the development and power of the Austro-Hungarian Navy. I was enchanted by everything I saw in both facilities. You should definitely visit the Pula Aquarium. It is relaxing, inspiring, enchanting. Highly recommended.", "The second part of the aquarium is located in the Baterija San Giovanni. Tickets must be purchased at the upper level. This section of the aquarium is dedicated to 'exotic' animal species and concludes with a marine exhibit. The aquariums are well worth seeing. Our children were thrilled. Important on hot days... the aquarium is air-conditioned. The conversion of the fort into an aquarium is also very well done. In short: absolutely worth seeing.", "The second part of the aquarium, with the larger animals."]}}

1. {"type": "cafe", "properties": {"tags": ["coffee", "pub", "beer", "city_center"], "outdoor_seating": true, "indoor_seating": true, "name": "Bounty", "phone": "+385 52 218 088", "opening_hours": "Mo-Su 07:00-23:00", "addr:housenumber": "8", "addr:street": "Veronska", "rating": 4.6, "description": "A cozy Irish-style pub in city center, known for draft beer, a wide drink selection, and a comfortable terrace with a relaxed atmosphere.", "reviews": ["An excellent Irish pub with a great Irish atmosphere. Clean, tidy, good to be here As it is a bit away from the busy tourist area, it is not crowded. Guinness and local beers on tap, plus a great selection of drinks. Shaded, comfortable terrace.", "Didn't get to stay here for long (one drink) however it has a real homely feel to the place and is a really nicely situated pub. Good atmosphere and seating options, good drink choices which are more foreign options (Guinness/Heineken/Jack Daniels etc) and the prices are quite good also! Would recommend stopping in for some drinks if in the local area!", "This is a proper bar. Beautiful inside. A nice seating area outside. They have a really good selection of drinks on offer."], "price": null}}
2. {"type": "pub", "properties": {"tags": ["coffee", "cocktails", "beer", "burgers", "fries", "seafood"], "outdoor_seating": true, "indoor_seating": null, "name": "Big Mama Beachbar", "phone": "+385 95 581 0900", "opening_hours": null, "addr:housenumber": null, "addr:street": "Valovine", "rating": 3.5, "description": null, "reviews": ["Fantastic beach bar with a relaxed atmosphere and stunning sea views. The drinks are refreshing, the staff is friendly, and the music creates the perfect summer vibe. A great place to unwind and enjoy the sunset!", "The food is delicious and the staff is excellent! A beautiful place for a beach holiday. Beautiful sunset.", "We passed this bar on a walk along the coast. On the terrace you can sit very nicely and watch the wakeboarders who are active on the wakeboard system. We had Coke and non-alcoholic beer, each from a local vendor and well chilled. Cheeseburgers and classic burgers were well fried and delicious. The fries were great and the fried calamari crispy. Everything was served on a beautiful wooden board plastic-free. The young man who served us was very nice and spoke a very good English."], "price": null}}
3. {"type": "pub", "properties": {"tags": ["coffee", "cocktails", "beer", "nightlife", "city_center"], "outdoor_seating": true, "indoor_seating": true, "name": "Old City Bar", "phone": "+385 52 222 944", "opening_hours": "Mo-Fr 06:30-02:30; Sa 07:00-02:00; Su 08:30-2:30", "addr:housenumber": "1", "addr:street": "Danteov trg", "rating": 4.5, "description": "A pub located in the center of Pula, offering a relaxed atmosphere during the day and lively parties at night. It is a popular spot for drinks, socializing, and weekend nightlife.", "reviews": ["Great service, Marcus was attentive and funny and made our night!! Drinks were all very good and really enjoyed the theatrics of the different shots and cocktails.", "Best Cocktails in town and super cool service personal, Marcus is our man! Come here! ✨🙌", "The service in this place cannot be compared to anything I've experienced so far of my nine days in Croatia. Not the cheapest, but the persistence and effort by Marco is why you pay a premium. The live music was also quite good. Awsome Bloody Mary if you're into that, and a selection of craft beer if that is your thing. (To Marco's employer, you should give this man a raise)"], "price": "medium"}}
4. {"type": "restaurant", "properties": {"tags": ["italian", "seafood", "pasta", "vegetarian", "vegan", "wine", "desserts", "city_center"], "outdoor_seating": true, "indoor_seating": true, "name": "Padela", "phone": "+385 91 6085 632", "opening_hours": "Mo-Su 09:00-22:00", "addr:housenumber": "2", "addr:street": "Riva", "rating": 4.9, "description": "A stylish waterfront restaurant on Pula’s Riva, specializing in handmade pasta, risotto, seafood, wine, and seasonal local ingredients.", "reviews": ["Excellent experience dining at this unique and wonderful restaurant! Beautifully decorated and very kind, professional service. We immediately felt welcomed. The waiter was also very helpful with describing the different dishes and house made pastas. Highly recommended.", "Fine dining with local touch and amazing ingredients. We were super amazed about the quality and taste of food. The pasta is perfectly cooked with carefully combined flavors and sauce. Thanks to the chef and team for the experience! 👏", "Padela is wonderful small restaurant with such a sweet atmosphere. Our server was so lovely and gave us exceptional wine recommendations. The pasta is to die for and the seafood is clearly very fresh. Highly recommend adding this place to your time in Pula!"], "price": "medium"}}
5. {"type": "cafe", "properties": {"tags": ["coffee", "wine", "cocktails", "city_center"], "outdoor_seating": true, "indoor_seating": true, "name": "Sirena", "phone": null, "opening_hours": "Mo-Fr 08:00-24:00; Sa-Su 09:00-24:00", "addr:housenumber": "12", "addr:street": "Forum", "rating": 4.1, "description": "A relaxed café on Pula’s main square, offering coffee, wine, cocktails, and terrace seating with views of the historic Forum.", "reviews": ["Wonderful place for coffee or a glass of delicious wine, with a view of the beautiful buildings around Forum Square. During our visits, we had the pleasure to meet waitress with long, slightly wavy hair — she was sooo cool and perfectly handled all orders. We'd love to come back! ❤️", "Nice terrace on the square! During the day, lots of shadow because of the wide parasols! The square is open, don’t get sunburned !", "Nice place, amazing coctails and lovely staff!"], "price": null}}

1. {"type": "sport", "properties": {"name": "Kayak Centar Pula", "tags": ["sports", "kayaking", "coastal", "family_friendly"], "description": "Kayak tours in Pula offer an active way to explore the coastline through paddling, snorkeling, and swimming, with options including island, cliff and cave tours, sunset paddles, morning tours, and kayak rentals for solo visitors, couples, or families.", "rating": 5.0, "reviews": ["We booked this tour via an enquiry through the website but received communication via Whatsapp, which was very helpful. We were able to clarify stuff and gave us confidence to book. Our guide was great, he knew the area well having grown up locally and was friendly and happy to chat with all of the group, as well as imparting his local knowledge. The kayaking route was brilliant, not too strenuous with lots of great views and a break for swimming, snorkelling (snorkel & mask provided) or relaxing. The drinks and snacks provided by the guide was a great touch. The guide also took plenty of 'action' pictures and we all received a link to download the pictures for FOC, great keepsakes. Definitely recommend.", "We had an amazing time on the 3-hour sea kayak excursion with Pula Kayak Centre! Toni, our guide, was fantastic super knowledgeable, friendly, and made the experience feel really personal. The scenery was absolutely stunning, with crystal-clear waters and beautiful coastal views. Toni took us to some hidden spots and made sure we were all comfortable and safe throughout. It was a perfect blend of adventure and relaxation. Highly recommend this tour to anyone looking for an unforgettable experience in Pula!", "Super nice! Really worth! We paid 26 euro for a 2 person Kayak in 2 hours. It was perfect time to explore some islands around Verudela!"]}}
2. {"type": "cafe", "properties": {"tags": ["coffee", "cocktails", "beer", "wine", "city_center"], "outdoor_seating": true, "indoor_seating": true, "name": "Caffe Bar Uliks", "phone": "+385 52 219 158", "opening_hours": "Mo-Su 07:00-02:00", "addr:housenumber": "1", "addr:street": "Trg Portarata", "rating": 4.5, "description": "A historic café bar in the very center of Pula, right next to the Arch of the Sergii, known for its literary connection to James Joyce, a wide drinks selection, specialty local spirits and craft beers, and a lively atmosphere with quizzes and other events.", "reviews": ["Would highly recommend! Really nice people inside and great vibes. The decor is so cool!", "Really lovely small pub, 10/10 would recommend for a quick pint. Cool statue of James Joyce outside who used to teach English in the building back yonder.", "Best place to watch Pula‘s life, friendly service, reasonable prices, my recommendation: the Negroni", "A nice cup of coffee on a beautiful spot next to the Arch of the Sergii."], "price": "medium"}}
3. {"type": "attraction", "properties": {"name": "kayak tours | pulsevents.hr", "tags": ["attraction", "kayaking", "coastal"], "description": "Guided kayak adventure in Pula offering coastal exploration, sea caves, snorkeling, and scenic views of the city’s rocky shoreline, suitable for both beginners and experienced paddlers.", "rating": 4.8, "reviews": ["It was an amazing experience with plenty of challenging activities included: kayaking, snorkeling, cliff jumping, passing through canals within the rocks. The monitors are super friendly, speakgood English and take good care of the group. It is easily doable with kids at the age of 7 and 13 in a three place kayak. The monitors made plenty of underwater photos of all member of the group with good quality cameras. Water or beers were provided at the bay when we stopped, just like the swimming Google's for snorkeling. Highly recommended.", "This was truly one of the best experiences of my life!! Jhonnes was an excellent guide who did everything he could to make it a great trip. He is also amazing at capturing picturesque moments. My family and friends that saw the pictures were in aww and asked who the photographer was. I would highly recommend this adventure to anyone considering it.", "A fantastic experience from start to finish. Well organised and very patient with us as inexperienced kayakers. We were kept updated and when our taxi left us in the wrong place a quick phonecall to them and they sorted everything to get us there on time. First class service, we were with teenagers who loved it too. Thank you"]}}
4. {"type": "park", "properties": {"name": "Park Monte Zaro", "tags": ["park", "historic", "hilltop", "observatory", "city_center", "family_friendly", "playground"], "description": "Largest historic park in Pula, set on a hill around the observatory, with fountains, Mediterranean trees, and scenic views over the city and harbour.", "rating": 4.5, "reviews": ["I didn’t expect much, but Montezaro Park turned out to be such a nice surprise. It’s quiet, full and perfect when you need a break from the heat and crowds. I grabbed a coffee and just walked around for a bit…. really relaxing spot with a great local feel.", "The roots of Montezaro Park are deeply embedded in Pula’s past. Originally designed in the 19th century, it was a retreat for nobility and a symbol of prestige. Small park that has a fountain, many trails to get around, and plenty of flora areas to enjoy. It's on a small hill so you can get some views of the surrounding area.", "A quiet city park on a hill overlooking Pula harbour, a welcome escape far from the madding crowd."]}}
5. {"type": "information", "properties": {"name": "Tourist Info Centre", "tags": ["information", "office", "city_center", "near_attractions"], "description": "Tourist information office in the heart of Pula on the Forum, offering maps, travel information, and visitor services from a historic building in the city’s main square.", "rating": 4.1, "reviews": ["Great, friendly service. Printed our boarding passes without charge when the EasyJet App did not work at the airport. Excellent", "For the first time, just a phone conversation. The employee was extremely kind, warm. She answered all my questions without any hesitation, simply and clearly. Thank you very much.", "Excellently trained and friendly team of employees always ready to help with information. A good team greatly contributes to the tourist offer of the city of Pula. Well done and keep up the good work."]}}

1. {"type": "beach", "properties": {"name": "Plaža Jupiter", "tags": ["beach", "island", "stone", "paved", "national_park", "family_friendly"], "description": "Well-maintained designated beach on Veli Brijun, known for its stone-paved shore, two spacious terraces, and relaxing atmosphere. It is one of the official swimming areas on the island, appreciated for its cleanliness, safety, and beautiful sunset views.", "rating": 4.1, "reviews": ["Jupiter Beach on Brijuni Island in Croatia is a true paradise! The water is crystal clear and ideal for children to swim and play safely. For snorkeling enthusiasts, this beach is an absolute dream – you can observe countless fish in their natural habitat. A perfect place to enjoy the beauty of the underwater world. Highly recommended!", "Cozy little beach"]}}
2. {"type": "cafe", "properties": {"tags": ["coffee", "cocktails", "beer", "wine", "city_center"], "outdoor_seating": true, "indoor_seating": true, "name": "Caffe Bar Uliks", "phone": "+385 52 219 158", "opening_hours": "Mo-Su 07:00-02:00", "addr:housenumber": "1", "addr:street": "Trg Portarata", "rating": 4.5, "description": "A historic café bar in the very center of Pula, right next to the Arch of the Sergii, known for its literary connection to James Joyce, a wide drinks selection, specialty local spirits and craft beers, and a lively atmosphere with quizzes and other events.", "reviews": ["Would highly recommend! Really nice people inside and great vibes. The decor is so cool!", "Really lovely small pub, 10/10 would recommend for a quick pint. Cool statue of James Joyce outside who used to teach English in the building back yonder.", "Best place to watch Pula‘s life, friendly service, reasonable prices, my recommendation: the Negroni", "A nice cup of coffee on a beautiful spot next to the Arch of the Sergii."], "price": "medium"}}
