3. {"type": "cafe", "properties": {"tags": ["coffee", "wine", "cocktails", "city_center"], "outdoor_seating": true, "indoor_seating": true, "name": "Sirena", "phone": null, "opening_hours": "Mo-Fr 08:00-24:00; Sa-Su 09:00-24:00", "addr:housenumber": "12", "addr:street": "Forum", "rating": 4.1, "description": "A relaxed café on Pula’s main square, offering coffee, wine, cocktails, and terrace seating with views of the historic Forum.", "reviews": ["Wonderful place for coffee or a glass of delicious wine, with a view of the beautiful buildings around Forum Square. During our visits, we had the pleasure to meet waitress with long, slightly wavy hair — she was sooo cool and perfectly handled all orders. We'd love to come back! ❤️", "Nice terrace on the square! During the day, lots of shadow because of the wide parasols! The square is open, don’t get sunburned !", "Nice place, amazing coctails and lovely staff!"], "price": null}}
4. {"type": "cafe", "properties": {"tags": ["coffee", "beer", "city_center"], "outdoor_seating": true, "indoor_seating": true, "name": "Scala", "phone": "+385 98 898 484", "opening_hours": null, "addr:housenumber": "1", "addr:street": "Ozad Arene", "rating": 4.0, "description": "A simple café bar right next to the Pula Arena, best known for its unique terrace with a direct view of the amphitheatre. It is a relaxed spot for coffee or a drink in one of the city’s most iconic locations.", "reviews": ["Perfect place to watch the Arena and enjoy a cold drink! Personnel is nice and friendly. Prices are regular. Have you never visited Croatia before? Try Pasareta, a real Croatian drink! 💪🏼 with lots of ice cubes, perfect! We only had drinks, no food. They have a lot of ice creams!", "Great coffee bar / drinks. Best spot in the area for a quiet coffee and to enjoy the arena. The staff all spoke many languages and were very helpful on giving local recommendations.", "Service extremely friendly and attentive. Nice ambience (with music from the amphitheater). Just perfect, where you feel comfortable and enjoy the sunset. Can only recommend👌"], "price": "medium"}}
5. {"type": "marina", "properties": {"name": "ACI Marina Pula", "tags": ["marina", "city_center", "restaurant", "near_attractions"], "description": "City marina in the heart of Pula, known for its protected harbour setting, full nautical services, boat rentals, and unique views of the Roman Arena.", "rating": 4.3, "reviews": ["ACI Marina in Pula is a top-notch spot for boaters and visitors alike. Well-maintained docks, friendly staff, and beautiful views make it perfect for sailing, relaxing by the water, or enjoying nearby cafes and restaurants.", "Very good Marina restaurant, helpful and friendly Marinero. Clean sanitary facilities, in the middle of the city. Can be noisy sometimes. Marina ist best contacted if you are already quite near if via VHF. Mobile phone is also possible.", "The marina is nice and spacious. You can walk above the coast and admire the boats and views."]}}

1. {"type": "beach", "properties": {"name": "Plaža Saluga", "tags": ["beach", "family_friendly", "national_park", "sand", "paved", "playground", "island", "wheelchair_accessible"], "description": null, "rating": 3.5, "reviews": ["A beautiful beach with a shower, a bench and a small park. It has an entrance to the sea for people with disabilities.", "A well-maintained beach for swimming, but not my type because it's concrete. There is shade and a bistro where you can eat and drink."]}}
2. {"type": "artwork", "properties": {"name": "Golub mira", "tags": ["artwork", "sculpture", "memorial", "national_park", "island"], "description": "A symbolic outdoor sculpture created by Dušan Džamonja and donated to the Brijuni archipelago in memory of Josip Broz Tito. Made of corten and formed from welded iron chains, it was conceived as a powerful expression of peace and freedom, combining modern artistic form with historical remembrance.", "rating": null, "reviews": null}}
3. {"type": "beach", "properties": {"name": "Plaža Jupiter", "tags": ["beach", "island", "stone", "paved", "national_park", "family_friendly"], "description": "Well-maintained designated beach on Veli Brijun, known for its stone-paved shore, two spacious terraces, and relaxing atmosphere. It is one of the official swimming areas on the island, appreciated for its cleanliness, safety, and beautiful sunset views.", "rating": 4.1, "reviews": ["Jupiter Beach on Brijuni Island in Croatia is a true paradise! The water is crystal clear and ideal for children to swim and play safely. For snorkeling enthusiasts, this beach is an absolute dream – you can observe countless fish in their natural habitat. A perfect place to enjoy the beauty of the underwater world. Highly recommended!", "Cozy little beach"]}}
4. {"type": "zoo", "properties": {"name": "Fazanerija", "tags": ["zoo", "animals", "family_friendly", "national_park", "island"], "description": "Small animal and bird area where visitors can see peacocks, turkeys, guinea fowl, parrots, and other birds, while the site also serves as a recovery and temporary care center for wild animals.", "rating": 4.1, "reviews": ["Don’t miss seeing this bird! Easy to find, unique experience", "Koji is awesome! He knows a few words, best one being 'tito'", "The animals seem content, and the facility was well-maintained. Of course, the buildings are old, and it's not a large zoo. But it's definitely worth a visit."]}}
5. {"type": "park", "properties": {"name": "Park Sergio Endrigo", "tags": ["park", "memorial", "near_attractions", "city_center"], "description": "Small urban park in central Pula dedicated to singer-songwriter Sergio Endrigo, with commemorative installations and occasional cultural events. Today it is mostly a quiet stop with a few benches and greenery, more suitable for a short pause than as a main attraction.", "rating": null, "reviews": null}}

1. {"type": "sport", "properties": {"name": "Kayak Centar Pula", "tags": ["sports", "kayaking", "coastal", "family_friendly"], "description": "Kayak tours in Pula offer an active way to explore the coastline through paddling, snorkeling, and swimming, with options including island, cliff and cave tours, sunset paddles, morning tours, and kayak rentals for solo visitors, couples, or families.", "rating": 5.0, "reviews": ["We booked this tour via an enquiry through the website but received communication via Whatsapp, which was very helpful. We were able to clarify stuff and gave us confidence to book. Our guide was great, he knew the area well having grown up locally and was friendly and happy to chat with all of the group, as well as imparting his local knowledge. The kayaking route was brilliant, not too strenuous with lots of great views and a break for swimming, snorkelling (snorkel & mask provided) or relaxing. The drinks and snacks provided by the guide was a great touch. The guide also took plenty of 'action' pictures and we all received a link to download the pictures for FOC, great keepsakes. Definitely recommend.", "We had an amazing time on the 3-hour sea kayak excursion with Pula Kayak Centre! Toni, our guide, was fantastic super knowledgeable, friendly, and made the experience feel really personal. The scenery was absolutely stunning, with crystal-clear waters and beautiful coastal views. Toni took us to some hidden spots and made sure we were all comfortable and safe throughout. It was a perfect blend of adventure and relaxation. Highly recommend this tour to anyone looking for an unforgettable experience in Pula!", "Super nice! Really worth! We paid 26 euro for a 2 person Kayak in 2 hours. It was perfect time to explore some islands around Verudela!"]}}
2. {"type": "attraction", "properties": {"name": "kayak tours | pulsevents.hr", "tags": ["attraction", "kayaking", "coastal"], "description": "Guided kayak adventure in Pula offering coastal exploration, sea caves, snorkeling, and scenic views of the city’s rocky shoreline, suitable for both beginners and experienced paddlers.", "rating": 4.8, "reviews": ["It was an amazing experience with plenty of challenging activities included: kayaking, snorkeling, cliff jumping, passing through canals within the rocks. The monitors are super friendly, speakgood English and take good care of the group. It is easily doable with kids at the age of 7 and 13 in a three place kayak. The monitors made plenty of underwater photos of all member of the group with good quality cameras. Water or beers were provided at the bay when we stopped, just like the swimming Google's for snorkeling. Highly recommended.", "This was truly one of the best experiences of my life!! Jhonnes was an excellent guide who did everything he could to make it a great trip. He is also amazing at capturing picturesque moments. My family and friends that saw the pictures were in aww and asked who the photographer was. I would highly recommend this adventure to anyone considering it.", "A fantastic experience from start to finish. Well organised and very patient with us as inexperienced kayakers. We were kept updated and when our taxi left us in the wrong place a quick phonecall to them and they sorted everything to get us there on time. First class service, we were with teenagers who loved it too. Thank you"]}}
3. {"type": "park", "properties": {"name": "Park Monte Zaro", "tags": ["park", "historic", "hilltop", "observatory", "city_center", "family_friendly", "playground"], "description": "Largest historic park in Pula, set on a hill around the observatory, with fountains, Mediterranean trees, and scenic views over the city and harbour.", "rating": 4.5, "reviews": ["I didn’t expect much, but Montezaro Park turned out to be such a nice surprise. It’s quiet, full and perfect when you need a break from the heat and crowds. I grabbed a coffee and just walked around for a bit…. really relaxing spot with a great local feel.", "The roots of Montezaro Park are deeply embedded in Pula’s past. Originally designed in the 19th century, it was a retreat for nobility and a symbol of prestige. Small park that has a fountain, many trails to get around, and plenty of flora areas to enjoy. It's on a small hill so you can get some views of the surrounding area.", "A quiet city park on a hill overlooking Pula harbour, a welcome escape far from the madding crowd."]}}
4. {"type": "city_gate", "properties": {"name": "Herkulova vrata", "tags": ["city_gate", "monument", "roman", "historic", "city_center", "landmark"], "description": "Ancient Roman city gate in Pula, known as the city’s oldest preserved Roman architectural monument, with a carved head of Hercules and an inscription linked to the founding of the Roman colony.", "rating": 4.3, "reviews": ["Small but historic. The Hercules Gate is easy to miss, but worth a quick stop. Ancient Roman carvings still visible—great for history lovers!", "Cool history, worth routing your walking path on your way to some of the more popular spots in Pula.", "The historical plaque is on the inside of the gate, making it hard to find, but still very picturesque."]}}
5. {"type": "viewpoint", "properties": {"name": "Cliff Diving", "tags": null, "description": null, "rating": null, "reviews": null}}

1. {"type": "artwork", "properties": {"name": "Golub mira", "tags": ["artwork", "sculpture", "memorial", "national_park", "island"], "description": "A symbolic outdoor sculpture created by Dušan Džamonja and donated to the Brijuni archipelago in memory of Josip Broz Tito. Made of corten and formed from welded iron chains, it was conceived as a powerful expression of peace and freedom, combining modern artistic form with historical remembrance.", "rating": null, "reviews": null}}
2. {"type": "artwork", "properties": {"name": "Marko Marulić", "tags": ["statue", "sculpture", "monument", "park", "artwork", "city_center"], "description": "A bronze public sculpture dedicated to one of the most important figures of Croatian literature, placed in a small park near the waterfront and the railway station. Its calm, dignified form reflects the intellectual and cultural legacy of the Renaissance writer, adding a literary and commemorative note to the surrounding urban landscape.", "rating": 4.0, "reviews": null}}
3. {"type": "artwork", "properties": {"name": "James Joyce", "tags": ["artwork", "statue", "historic", "city_center", "landmark", "near_attractions"], "description": "Bronze statue of James Joyce in central Pula near the Arch of the Sergii, commemorating the famous Irish writer’s stay in the city and its place in his early literary life.", "rating": 4.7, "reviews": ["This statue made we search more about this Irish novelist. He was an important writer whose books are read today. Here you can take selfies with the statue and enjoy a cup of coffee in a table next to the statue.", "Nice sculpture. Beside a restaurant. If not known, or checked carefully, one can miss it for a person waiting outside a restaurant.", "Nice statue. You can sit with him."]}}
4. {"type": "artwork", "properties": {"name": "Spomenik streljanim mornarima", "tags": ["sculpture", "monument", "memorial", "historic", "city_center", "near_attractions"], "description": "Memorial sculpture in Valerijin park in Pula, dedicated to the sailor and associated with the remembrance of the 1918 sailors’ revolt in the Bay of Kotor.", "rating": null, "reviews": null}}
5. {"type": "attraction", "properties": {"name": "LABIRINT OSJEĆAJA", "tags": ["attraction", "labyrinth", "meditative", "nature", "stone"], "description": "Stone labyrinth in Šijanska šuma designed for reflective walking and a symbolic experience connected with emotions, sensitivity, calmness, and inner harmony.", "rating": null, "reviews": null}}

1. {"type": "viewpoint", "properties": {"name": "Vidikovac Javornik", "tags": ["viewpoint", "national_park", "island", "historic", "nature"], "description": "Restored historic viewpoint on Veliki Brijun, known for its Austro-Hungarian metal structure, peaceful forest setting, and panoramic views over the island, sea, and nearby islets.", "rating": 4.6, "reviews": ["Pretty great spot for a look out - multi layered observation tower in the middle of the forest, easy to climb up, and lots of space on top to view all around. There's several benches. It is a bit more overgrown with trees, so views somewhat obstructed. This place is a bit difficult to get to, no clear signs - there's only one main trail from the north, it's not paved; you do not have access from the side of the villas.", "Forest covered most of the view but still very nice to visit as it has few benches on the top of the tower to relax and enjoy the view and the breeze.", "Nice place, not much of a view since surrounding forest outgrew the structure - on the plus side, very quiet and peaceful place"]}}
2. {"type": "fort", "properties": {"name": "Fort Brioni Minor", "tags": ["fortress", "historic", "coastal", "military_history", "national_park", "island", "events"], "description": "Large Austro-Hungarian coastal fortress on Mali Brijun, known for its preserved military architecture, strategic sea-facing position, and summer theatre performances held within the fort.", "rating": 4.8, "reviews": ["We have a chance to enjoy there as part of the King Lear play. Fortress is amasing an perfectly fitted the show.", "Amazing still standing fortress from the beginning of 20th century. Used by Ulysses theatre", "A beautiful place, lots of wonderful things to see, from rich flora and fauna to beautiful historical buildings."]}}
3. {"type": "cafe", "properties": {"tags": ["coffee", "cocktails", "beer", "wine", "city_center"], "outdoor_seating": true, "indoor_seating": true, "name": "Caffe Bar Uliks", "phone": "+385 52 219 158", "opening_hours": "Mo-Su 07:00-02:00", "addr:housenumber": "1", "addr:street": "Trg Portarata", "rating": 4.5, "description": "A historic café bar in the very center of Pula, right next to the Arch of the Sergii, known for its literary connection to James Joyce, a wide drinks selection, specialty local spirits and craft beers, and a lively atmosphere with quizzes and other events.", "reviews": ["Would highly recommend! Really nice people inside and great vibes. The decor is so cool!", "Really lovely small pub, 10/10 would recommend for a quick pint. Cool statue of James Joyce outside who used to teach English in the building back yonder.", "Best place to watch Pula‘s life, friendly service, reasonable prices, my recommendation: the Negroni", "A nice cup of coffee on a beautiful spot next to the Arch of the Sergii."], "price": "medium"}}
4. {"type": "restaurant", "properties": {"tags": ["international", "grill", "meat", "pasta", "burgers", "beer", "wine", "cocktails", "vegetarian", "city_center"], "outdoor_seating": false, "indoor_seating": true, "name": "Kinema", "phone": "+385 99 164 4949", "opening_hours": "Mo-Th 10:00-23:00, Fr,Sa 10:00-24:00, Su 12:00-23:00", "addr:housenumber": "12", "addr:street": "Flavijevska", "rating": 4.7, "description": "A modern pub and restaurant in Pula with a lively social atmosphere, combining great food, drinks, and entertainment in one place. Kinema is known for billiards, darts, live sports screenings, themed events, burgers, steaks, breakfast, local wines, cocktails, and craft beer, making it a popular spot for both casual hangouts and nights out with friends.", "reviews": ["Fantastic bar/restaurant. Visiting from England I was looking for somewhere to watch the Aston Villa match, walked in I believe I met the owner, said he had the game on, minute later a guy came over and said you want the Villa game on the big screen, yes I said, that’s great hospitality! The bar is extremely cool, strangely it smells wonderful in there, darts, pool all can be played. Food is excellent, we had a grazing board and chicken wings, spot on they was. Staff, really friendly and welcoming, sorry about this as I couldn’t remember her name, but Drag….. was first class.", "One of the best restaurants in Pula, especially if you’re looking for a place to eat near the Pula Arena. The food portions were huge, definitely more than enough for one person, and we left feeling very full and satisfied. The drinks were excellent and had a classy touch. The ambiance was fantastic, with great entertainment and we didn’t even realize we had stayed for over 3 hours! Highly recommended.", "What a venue! If you are looking for live sports, pool, darts or just a good atmosphere, head here. An old cinema has been transformed into a superb sports bar. A small doorway opens up to this vast multi room venue, and the screen is maaaasssssiiiiiiiivvveee. A nice welcome to fast knowledgeable service & they go to every effort to accommodate your needs. After the large main room, there's a pool room off to one side & another more intimate balcony area upstairs. The atmosphere is not too loud, so you have to shout, and the other guests are all smiling and up to banter. The menu does not do justice to the food, which was excellent. A mix of burgers, etc, to more traditional dishes Generous portios, to say the least, could not even look at the desserts menu. A real gem * kids are welcome", "This was the best restaurant I've visited in Pula. Pavle, the server was extremely pleasant and welcoming, he gave some great suggestions. I came in only to have some coffee but ended up getting the breakfast and dessert. Couldn't tell which was better. Extremely well made food, with even better staff. I couldn't recommend this place more!"], "price": "medium"}}
5. {"type": "cafe", "properties": {"tags": ["coffee", "pub", "beer", "city_center"], "outdoor_seating": true, "indoor_seating": true, "name": "Bounty", "phone": "+385 52 218 088", "opening_hours": "Mo-Su 07:00-23:00", "addr:housenumber": "8", "addr:street": "Veronska", "rating": 4.6, "description": "A cozy Irish-style pub in city center, known for draft beer, a wide drink selection, and a comfortable terrace with a relaxed atmosphere.", "reviews": ["An excellent Irish pub with a great Irish atmosphere. Clean, tidy, good to be here As it is a bit away from the busy tourist area, it is not crowded. Guinness and local beers on tap, plus a great selection of drinks. Shaded, comfortable terrace.", "Didn't get to stay here for long (one drink) however it has a real homely feel to the place and is a really nicely situated pub. Good atmosphere and seating options, good drink choices which are more foreign options (Guinness/Heineken/Jack Daniels etc) and the prices are quite good also! Would recommend stopping in for some drinks if in the local area!", "This is a proper bar. Beautiful inside. A nice seating area outside. They have a really good selection of drinks on offer."], "price": null}}

1. {"type": "beach", "properties": {"name": "Plaža Jupiter", "tags": ["beach", "island", "stone", "paved", "national_park", "family_friendly"], "description": "Well-maintained designated beach on Veli Brijun, known for its stone-paved shore, two spacious terraces, and relaxing atmosphere. It is one of the official swimming areas on the island, appreciated for its cleanliness, safety, and beautiful sunset views.", "rating": 4.1, "reviews": ["Jupiter Beach on Brijuni Island in Croatia is a true paradise! The water is crystal clear and ideal for children to swim and play safely. For snorkeling enthusiasts, this beach is an absolute dream – you can observe countless fish in their natural habitat. A perfect place to enjoy the beauty of the underwater world. Highly recommended!", "Cozy little beach"]}}
2. {"type": "cafe", "properties": {"tags": ["coffee", "pub", "beer", "city_center"], "outdoor_seating": true, "indoor_seating": true, "name": "Bounty", "phone": "+385 52 218 088", "opening_hours": "Mo-Su 07:00-23:00", "addr:housenumber": "8", "addr:street": "Veronska", "rating": 4.6, "description": "A cozy Irish-style pub in city center, known for draft beer, a wide drink selection, and a comfortable terrace with a relaxed atmosphere.", "reviews": ["An excellent Irish pub with a great Irish atmosphere. Clean, tidy, good to be here As it is a bit away from the busy tourist area, it is not crowded. Guinness and local beers on tap, plus a great selection of drinks. Shaded, comfortable terrace.", "Didn't get to stay here for long (one drink) however it has a real homely feel to the place and is a really nicely situated pub. Good atmosphere and seating options, good drink choices which are more foreign options (Guinness/Heineken/Jack Daniels etc) and the prices are quite good also! Would recommend stopping in for some drinks if in the local area!", "This is a proper bar. Beautiful inside. A nice seating area outside. They have a really good selection of drinks on offer."], "price": null}}
3. {"type": "attraction", "properties": {"name": "kayak tours | pulsevents.hr", "tags": ["attraction", "kayaking", "coastal"], "description": "Guided kayak adventure in Pula offering coastal exploration, sea caves, snorkeling, and scenic views of the city’s rocky shoreline, suitable for both beginners and experienced paddlers.", "rating": 4.8, "reviews": ["It was an amazing experience with plenty of challenging activities included: kayaking, snorkeling, cliff jumping, passing through canals within the rocks. The monitors are super friendly, speakgood English and take good care of the group. It is easily doable with kids at the age of 7 and 13 in a three place kayak. The monitors made plenty of underwater photos of all member of the group with good quality cameras. Water or beers were provided at the bay when we stopped, just like the swimming Google's for snorkeling. Highly recommended.", "This was truly one of the best experiences of my life!! Jhonnes was an excellent guide who did everything he could to make it a great trip. He is also amazing at capturing picturesque moments. My family and friends that saw the pictures were in aww and asked who the photographer was. I would highly recommend this adventure to anyone considering it.", "A fantastic experience from start to finish. Well organised and very patient with us as inexperienced kayakers. We were kept updated and when our taxi left us in the wrong place a quick phonecall to them and they sorted everything to get us there on time. First class service, we were with teenagers who loved it too. Thank you"]}}
4. {"type": "hostel", "properties": {"name": "Hostel Art & Joy", "tags": ["hostel", "free_parking", "garden", "family_friendly"], "description": "Friendly hostel in Pula with a garden, terrace, shared kitchen, and convenient access to the Arena and other city attractions.", "rating": 3.8, "reviews": ["We had an amazing stay in this hostel. The staff is very nice and helpful : the receptionist gave us tips on what to see and visit around the city, helped us book bikes. We were also able to change beds to be closer to each other in the room. The bedrooms and common rooms are cleaned daily and the air conditioning was appreciated. The hostel is well located, there are bus stops right next to it, it’s only a 10-minutes walk to the city center. As 2 girls travelling, we felt very confortable and safe staying at this hostel. People we met there were easygoing and we had some really nice times in the kitchen and on the terrace. To sum up : we had a wonderful vacation in Pula :) PS : the only thing that’s missing would be board games accessible to everyone.", "We had a nice stay in the private room. Everything is clean, the staff is friendly, pizzeria next door. The cute mosaique and artistic flair got us lost in long conversations about art and the meaning of life ;)", "I have stayed in Pula 5 times now. The first time was at an apartment with restricted check in times. 3pm to 5pm only. And a long walk to the centre.I was in a restaurant chatting to someone on the next table.He recommended Art and Joy hostel. I took a walk there the next day. His advice was spot on. I met the manager there and said may I have a look inside, with a possibility of staying there the following year. She agreed. Wow it was great I thought. So I booked for the next Summer. I wasn't disappointed. I have now stayed 4 times each Summer for 4 years.Close to the centre, and the staff are superb. They will help you with any issues you may have.. The hard working cleaner is great also. I recommend it. Choice of rooms to suit your requirements.And good value.. Give it a try for a few nights and then extend it if you want to. Obviously subject to availability."]}}
5. {"type": "cafe", "properties": {"tags": ["balkan", "coffee", "beer"], "outdoor_seating": true, "indoor_seating": true, "name": "Caffe Bar Nozi 7", "phone": null, "opening_hours": "Mo-Tu 05:00-23:00; We-Su 05:00-22:00", "addr:housenumber": "9", "addr:street": "Trg I istarske brigade", "rating": 4.0, "description": "A casual café at Pula’s bus station, suitable for a quick coffee, soft drink, beer, or short stop while waiting for transport.", "reviews": ["This coffee is very close to the bus station. It's clean. The service is quick. The prices are very good 👍 It is a very good place to take a coffee when waiting for your bus :)", "Took the shuttle bus from Pula airport to Pula bus station. 30 kuna (£3.30) each. 15 mins. Hour to kill before bus to heaven ( Rovinj) so popped into this lovely cafe with attached bakery opposite. First beer of the holiday. Great place to wait. Also toilet in bus station has a pay turnstile unlike here. Tabke service for drinks; go to bakery for food. Excellent value. 88Kuna / £10 for 2 coffee and 4*0.33l beers."], "price": "low"}}

1. {"type": "memorial", "properties": {"name": "Lino Mariani", "tags": ["bust", "memorial", "historic", "city_center", "near_attractions"], "description": "A bronze memorial bust dedicated to an antifascist partisan, trade unionist and worker remembered for his role in the turbulent post-war history of Pula. Placed near the ancient city walls and Hercules Gate, it adds a modern historical layer to this Roman setting and commemorates local resistance, labour struggle and civic memory.", "rating": 4.5, "reviews": null}}
2. {"type": "memorial", "properties": {"name": "Spomenik Vladimiru Gortanu", "tags": ["sculpture", "memorial", "monument", "historic", "near_beach", "coastal"], "description": "Memorial sculpture on Lungomare in Pula dedicated to Vladimir Gortan, an important symbol of Istrian anti-fascist resistance, placed near the site where he was executed in 1929.", "rating": 4.6, "reviews": ["Beautiful monument. What is sad, apart from the story about Gortan himself, is that it's a wild parking place with cars parked 20cm from the monument all around it."]}}
3. {"type": "restaurant", "properties": {"tags": ["mediterranean", "seafood", "pasta", "wine", "cocktails", "hotel_restaurant"], "outdoor_seating": true, "indoor_seating": true, "name": "Vela Nera", "phone": "+385 52 300 620", "opening_hours": null, "addr:housenumber": "3b", "addr:street": "Franje Mošnja", "rating": 4.7, "description": "A stylish hotel restaurant in Šišan near Pula, serving Mediterranean and Istrian cuisine, local wines, cocktails, business lunches, and catering in an elegant setting.", "reviews": ["Everything was impressive, we stayed for a couple of days and we had a really good time. In addition the food from the breakfast and the restaurant was delicious with an excellent presentation. Finally, the staff was super friendly and really professional!", "This is a gem! A great family run hotel with amazing food. The service is just wonderful with an attitude that makes everything possible. I stayed 8 nights in a very spacious super clean room. I enjoyed the pool and the fabulous food. It was truly a home away from home. For me the location was great, easy drives into the main tourist areas for work while I could enjoy the off the beaten track feel of the calm village. I am hoping to go back for leisure with my family.", "Went for food as part of our wedding anniversary celebrations. The service was fantastic, the food was absolutely brilliant. We had beef steak and tuna steak which were both cooked to perfection. The deserts were wonderful, apple strudel and a chocolate souffle. Great evening in a fantastic setting to watch the sun go down over a tasty bottle of wine which was superbly recommended by our waiter."], "price": "high"}}
4. {"type": "restaurant", "properties": {"tags": ["mediterranean", "seafood", "steak", "pasta", "wine", "city_center"], "outdoor_seating": true, "indoor_seating": null, "name": "Veritas Food & Wine", "phone": "+385 97 656 3627", "opening_hours": "Mo-Su 10:00-23:00", "addr:housenumber": "14", "addr:street": "Maksimijanova", "rating": 4.9, "description": "A family-run restaurant in the heart of Pula, known for seafood, steaks, pasta, Istrian wines, and a romantic atmosphere beside historic landmarks.", "reviews": ["We were having an amazing experience. Tonight we try all the productes with truffles. Pasta with truffles, steak with truffles and fish fillet with truffles, they even have beer with truffles!! For start we had 2 Hibiki Japanese whiskeys, and later with the food we shared a bottle of Matosevic Grimalda.", "Some of the best fishing scampi I've had. Already had high expectations with the great reviews but this blew me away. Definitely coming back on our next visit.", "Walking by I thought this restaurant was super cute and then looking at the menu, my husband and I walked back to go. We are so thankful we did! The food was amazing. The service was impeccable. They paired the drinks perfectly, recommended the freshest and best dishes, and even gave you the option to clean the fish themselves at the table. Very personable and friendly staff who work as a team but gave you the space to enjoy your time. The view and breeze was an added bonus. If I could give more stars, I absolutely would. Adding to my files of recommended eateries to share with family and friends who travel to Pula!", "We just had dinner here and it was above and beyond what we were expecting. We had a few dinners in Pula that were just okay but this was amazing. Arian gave excellent service while handling a huge section and a wait. We tried the scallops and local cheese for an appetizer. The scallops were perfectly prepared and the cheese was all local. Now for the main dishes. My better half had the lamb. Completely drool worthy, while I on the other hand had the truffle steak with the hand made pasta. Look no further! This was the best steak I have ever had. If we lived here we would come every week. The biggest issue is now I feel like I need truffles in every thing!"], "price": "high"}}
5. {"type": "artwork", "properties": {"name": "Marko Marulić", "tags": ["statue", "sculpture", "monument", "park", "artwork", "city_center"], "description": "A bronze public sculpture dedicated to one of the most important figures of Croatian literature, placed in a small park near the waterfront and the railway station. Its calm, dignified form reflects the intellectual and cultural legacy of the Renaissance writer, adding a literary and commemorative note to the surrounding urban landscape.", "rating": 4.0, "reviews": null}}

1. {"type": "cafe", "properties": {"tags": ["coffee", "cocktails", "beer", "wine", "city_center"], "outdoor_seating": true, "indoor_seating": true, "name": "Caffe Bar Uliks", "phone": "+385 52 219 158", "opening_hours": "Mo-Su 07:00-02:00", "addr:housenumber": "1", "addr:street": "Trg Portarata", "rating": 4.5, "description": "A historic café bar in the very center of Pula, right next to the Arch of the Sergii, known for its literary connection to James Joyce, a wide drinks selection, specialty local spirits and craft beers, and a lively atmosphere with quizzes and other events.", "reviews": ["Would highly recommend! Really nice people inside and great vibes. The decor is so cool!", "Really lovely small pub, 10/10 would recommend for a quick pint. Cool statue of James Joyce outside who used to teach English in the building back yonder.", "Best place to watch Pula‘s life, friendly service, reasonable prices, my recommendation: the Negroni", "A nice cup of coffee on a beautiful spot next to the Arch of the Sergii."], "price": "medium"}}
2. {"type": "marina", "properties": {"name": "ACI Marina Pula", "tags": ["marina", "city_center", "restaurant", "near_attractions"], "description": "City marina in the heart of Pula, known for its protected harbour setting, full nautical services, boat rentals, and unique views of the Roman Arena.", "rating": 4.3, "reviews": ["ACI Marina in Pula is a top-notch spot for boaters and visitors alike. Well-maintained docks, friendly staff, and beautiful views make it perfect for sailing, relaxing by the water, or enjoying nearby cafes and restaurants.", "Very good Marina restaurant, helpful and friendly Marinero. Clean sanitary facilities, in the middle of the city. Can be noisy sometimes. Marina ist best contacted if you are already quite near if via VHF. Mobile phone is also possible.", "The marina is nice and spacious. You can walk above the coast and admire the boats and views."]}}
3. {"type": "cafe", "properties": {"tags": ["mediterranean", "coffee", "gallery", "cocktails", "ice_cream", "desserts", "city_center"], "outdoor_seating": true, "indoor_seating": true, "name": "Cvajner", "phone": "+385 52 216 502", "opening_hours": "Mo-Sa 08:00-23:00; Su 10:00-23:00", "addr:housenumber": "2", "addr:street": "Forum", "rating": 4.3, "description": "Art café and gallery on Pula’s main square, known for its striking historic interior, artistic atmosphere, and terrace overlooking the Forum and the Temple of Augustus.", "reviews": ["Great place to get some coffee and quick food; located right in Forum Square, so finding this place is super simple. Service could be a bit better and more organized, but otherwise everything was super tasty.", "Very nice iced coffee. Cozy enviroment, interesting design with restored paintings on the walls.", "This is in a great location if you sit outside. The Forum has a great buzz and is beautiful. Prices are quite reasonable for such a location (big draught beer €4.2) Most of the staff are busy and seem a bit a bit grumpy ( except one nice waitress) There are small menus on the tables and bills are clearly itemised. We saw a family leave after waiting ages to be served. Inside looks nice too with some old frescos. Locals here too. Worth a visit though.", "Gorgeous and cosy caffe... Well preserved historical charm done by keeping the original tapestry and blending it in with the new one. Drinks are well made and the staff is polite, very nice place to come to on a rainy day."], "price": "medium"}}
4. {"type": "hostel", "properties": {"name": "Sol Garden - Hostel with a Soul", "tags": ["hostel", "near_attractions"], "description": "A simple and budget-friendly stay close to Pula Arena and the city’s historic center, offering dormitories and twin rooms with access to shared bathrooms. Guests can use a fully equipped shared kitchen, relax in the garden or on the terrace, and easily reach the waterfront, restaurants, bars and main transport connections on foot.", "rating": 5.0, "reviews": ["The hostel was very clean, it had a pleasant smell, and it was very quiet. It has a large kitchen and a spacious balcony. In the rooms, there are also small lockers that can be locked using the card provided by the reception to access the doors. Nearby, there are 2–3 markets, a coffee bar, and it is also close to the Arena as well as the bus station.", "The hostel is very good, quiet, and has several places nearby such as markets, coffee bars, and other shops. It also has a nice balcony, a large kitchen, and spacious bathrooms. The rooms are clean, air-conditioned, and everything is in order.", "Location and Staff! Excellent environment"]}}
5. {"type": "cafe", "properties": {"tags": ["wine", "cocktails", "beer", "breakfast", "brunch", "sandwiches", "desserts", "ice_cream", "city_center"], "outdoor_seating": true, "indoor_seating": true, "name": "Enoteca Istriana", "phone": "+385 99 323 6541", "opening_hours": "Mo-Su 09:00-21:00", "addr:housenumber": "11", "addr:street": "Forum", "rating": 3.6, "description": "A wine and coffee bar in the heart of Pula’s old town, right on Forum square by the Temple of Augustus, known for its wide selection of Istrian wines and craft beers.", "reviews": ["Visited this wine bar 4 times during our stay in Pula for coffee, wine, ice cream and sandwiches in a relaxed warm friendly atmosphere. The service was fast and efficient provided by staff who were friendly and accommodating. I highly recommend this wine bar will revisit on a return to Pula.", "Very good place for coffee and verry kind staff. Breakfast is good , this is the best place of the square!"], "price": null}}

1. {"type": "hostel", "properties": {"name": "Sol Garden - Hostel with a Soul", "tags": ["hostel", "near_attractions"], "description": "A simple and budget-friendly stay close to Pula Arena and the city’s historic center, offering dormitories and twin rooms with access to shared bathrooms. Guests can use a fully equipped shared kitchen, relax in the garden or on the terrace, and easily reach the waterfront, restaurants, bars and main transport connections on foot.", "rating": 5.0, "reviews": ["The hostel was very clean, it had a pleasant smell, and it was very quiet. It has a large kitchen and a spacious balcony. In the rooms, there are also small lockers that can be locked using the card provided by the reception to access the doors. Nearby, there are 2–3 markets, a coffee bar, and it is also close to the Arena as well as the bus station.", "The hostel is very good, quiet, and has several places nearby such as markets, coffee bars, and other shops. It also has a nice balcony, a large kitchen, and spacious bathrooms. The rooms are clean, air-conditioned, and everything is in order.", "Location and Staff! Excellent environment"]}}
2. {"type": "hostel", "properties": {"name": "MONTE ZARO", "tags": ["hostel", "city_center", "free_parking", "family_friendly"], "description": "Modern hostel in Pula with private bathrooms, breakfast, free parking, and a convenient location close to city attractions.", "rating": 4.0, "reviews": ["We were here in August 2025 And it was perfect, receptionists were always nice and helpfull, the breakfast was delicious, the room was clean, new and quite nice. The location is perfect, we were 10 minutes away from the city center. So basically, i recommend this hostel to anyone, who don’t want to Pay big cash, but do want to spend time in comfort accommodation.", "Nice apartment for one night stay. Walking distance from city centre, Arena. Useful kitchen. Good value for money.", "Perfect location if you want to explore the city of Pula by foot. The room was clean and the staff was very helpful. Walls are quite thin and you can hear other people in the hall."]}}
3. {"type": "hostel", "properties": {"name": "Art Hostel Pipištrelo", "tags": ["hostel", "city_center", "family_friendly", "pet_friendly", "near_attractions"], "description": "Hostel Pipištrelo is a small, stylish hostel in the heart of Pula, just a short walk from the Forum, Arena, Kastel and other main sights of the old town. It offers air-conditioned rooms, free WiFi, a shared lounge and a shared kitchen, combining a central location with a simple, comfortable stay. With only a few rooms and artistic details throughout the interior, the hostel has a more intimate, boutique feel than a classic budget hostel.", "rating": 4.1, "reviews": ["Always ready for help with anything or any need. Maybe a little tomuch aerosols but I air the room before .", "Perfect location with a view of the water from our room, 1km from amphitheater, and only minutes to walk to all restaurants and shops. Beaches 10 mins by bus. It was hot during our stay, and communal areas do not have aircon.", "Great location walking distance to plenty of bars/restaurants. Clean rooms and very responsive host. Highly recommend!"]}}
4. {"type": "park", "properties": {"name": "Park grada Graza", "tags": ["park", "city_center", "family_friendly", "pet_friendly", "historic", "playground"], "description": "Central city park in Pula, created after World War II and known for its shade, archaeological fragments, and relaxed atmosphere near the Forum.", "rating": 4.5, "reviews": ["I love this little hideaway before the forum. Nice place to sit and think about life while under the shade of a small tree", "Peaceful park with ancient fragments all over the place among children’s swings makes for an interesting contrast", "Fantastic for kids! A couple of advent houses, a small funfair just right for everyone... for both the little ones and the big ones! Enough for everyone! Just right today, not crowded or too many people... The temperature is pleasant for December 2025!"]}}
5. {"type": "marina", "properties": {"name": "ACI Marina Pula", "tags": ["marina", "city_center", "restaurant", "near_attractions"], "description": "City marina in the heart of Pula, known for its protected harbour setting, full nautical services, boat rentals, and unique views of the Roman Arena.", "rating": 4.3, "reviews": ["ACI Marina in Pula is a top-notch spot for boaters and visitors alike. Well-maintained docks, friendly staff, and beautiful views make it perfect for sailing, relaxing by the water, or enjoying nearby cafes and restaurants.", "Very good Marina restaurant, helpful and friendly Marinero. Clean sanitary facilities, in the middle of the city. Can be noisy sometimes. Marina ist best contacted if you are already quite near if via VHF. Mobile phone is also possible.", "The marina is nice and spacious. You can walk above the coast and admire the boats and views."]}}

1. {"type": "park", "properties": {"name": "Park Monte Zaro", "tags": ["park", "historic", "hilltop", "observatory", "city_center", "family_friendly", "playground"], "description": "Largest historic park in Pula, set on a hill around the observatory, with fountains, Mediterranean trees, and scenic views over the city and harbour.", "rating": 4.5, "reviews": ["I didn’t expect much, but Montezaro Park turned out to be such a nice surprise. It’s quiet, full and perfect when you need a break from the heat and crowds. I grabbed a coffee and just walked around for a bit…. really relaxing spot with a great local feel.", "The roots of Montezaro Park are deeply embedded in Pula’s past. Originally designed in the 19th century, it was a retreat for nobility and a symbol of prestige. Small park that has a fountain, many trails to get around, and plenty of flora areas to enjoy. It's on a small hill so you can get some views of the surrounding area.", "A quiet city park on a hill overlooking Pula harbour, a welcome escape far from the madding crowd."]}}
2. {"type": "park", "properties": {"name": "Park Sergio Endrigo", "tags": ["park", "memorial", "near_attractions", "city_center"], "description": "Small urban park in central Pula dedicated to singer-songwriter Sergio Endrigo, with commemorative installations and occasional cultural events. Today it is mostly a quiet stop with a few benches and greenery, more suitable for a short pause than as a main attraction.", "rating": null, "reviews": null}}
3. {"type": "cafe", "properties": {"tags": ["coffee", "ice_cream", "cocktails", "sandwiches", "desserts", "city_center"], "outdoor_seating": true, "indoor_seating": true, "name": "Kukuriku", "phone": "+385 52 210 498", "opening_hours": "Mo-Th 07:00-23:00; Fr-Sa 07:00-24:00; Su 07:30-23:00", "addr:housenumber": "7", "addr:street": "Istarska", "rating": 4.0, "description": "A relaxed city-center café, offering coffee, cocktails and casual sweet and savory snacks in a pleasant outdoor setting.", "reviews": ["Nice place, friendly waiter and really tasty food", "Loved this place! It has really good chocolate croissants and the cappuccino is also very good.", "Nice place in city center. A bit pricey. Aperol spritz 8eur, Hugo the same. Staff was nice and professional."], "price": "medium"}}
4. {"type": "apartment", "properties": {"name": "Vea Histria Apartments Pula", "tags": ["apartment", "family_friendly"], "description": "Elegant and well-equipped apartments in a quieter part of Pula, designed for a comfortable and practical stay close to the city and nearby beaches. The units offer private terraces, modern kitchens, air conditioning, Wi-Fi and parking, making them a convenient choice for couples, families and guests who want easy access to both urban attractions and the coast.", "rating": 4.7, "reviews": ["Very good location, close to shops, restaurants, city center, port, Roman arena. It has its own parking which is a big plus for Croatia, where it is hard to find parking and everything is for a fee (price varies between 1.5-4 euros/hour). The beds are comfortable, apartment equipped with everything you need, it is spacious. Check-in is easy, you get the details from the owner. You are also close to the sea (which is rocky, you definitely need water shoes, otherwise you can't go).", "The apartment was comfortable and clean, spacious enough, and not too hot despite the 35°C (95°F) outside. Convenient check-in and check-out, and car parking available. The location was also convenient, very close to the ring road, for us who traveled a lot in the surrounding area. If I were to return to Pula, this would be my first choice.", "I recommend this place. The owner is always helpful. Quiet and peaceful."]}}
5. {"type": "fountain", "properties": {"name": "Maketa Pule", "tags": ["tactile_model", "city_center", "interactive", "family_friendly", "near_attractions"], "description": "Interactive tactile model of Pula in the city centre, offering a detailed 3D overview of the city layout, waterways, and key landmarks in a quick and educational way.", "rating": 4.7, "reviews": ["I love seeing the miniature cities; and this one is even cooler because it has water spouting where the Adriatic Sea is; really neat.", "Small model of the city of Pula, with water. Good for exploring the city. Made of metal.", "A visual miniature of the charming city of Pula. It's a great introduction to general knowledge. I highly recommend it."]}}

1. {"type": "cafe", "properties": {"tags": ["coffee", "cocktails", "beer", "wine", "city_center"], "outdoor_seating": true, "indoor_seating": true, "name": "Caffe Bar Uliks", "phone": "+385 52 219 158", "opening_hours": "Mo-Su 07:00-02:00", "addr:housenumber": "1", "addr:street": "Trg Portarata", "rating": 4.5, "description": "A historic café bar in the very center of Pula, right next to the Arch of the Sergii, known for its literary connection to James Joyce, a wide drinks selection, specialty local spirits and craft beers, and a lively atmosphere with quizzes and other events.", "reviews": ["Would highly recommend! Really nice people inside and great vibes. The decor is so cool!", "Really lovely small pub, 10/10 would recommend for a quick pint. Cool statue of James Joyce outside who used to teach English in the building back yonder.", "Best place to watch Pula‘s life, friendly service, reasonable prices, my recommendation: the Negroni", "A nice cup of coffee on a beautiful spot next to the Arch of the Sergii."], "price": "medium"}}
2. {"type": "marina", "properties": {"name": "ACI Marina Pula", "tags": ["marina", "city_center", "restaurant", "near_attractions"], "description": "City marina in the heart of Pula, known for its protected harbour setting, full nautical services, boat rentals, and unique views of the Roman Arena.", "rating": 4.3, "reviews": ["ACI Marina in Pula is a top-notch spot for boaters and visitors alike. Well-maintained docks, friendly staff, and beautiful views make it perfect for sailing, relaxing by the water, or enjoying nearby cafes and restaurants.", "Very good Marina restaurant, helpful and friendly Marinero. Clean sanitary facilities, in the middle of the city. Can be noisy sometimes. Marina ist best contacted if you are already quite near if via VHF. Mobile phone is also possible.", "The marina is nice and spacious. You can walk above the coast and admire the boats and views."]}}
3. {"type": "cafe", "properties": {"tags": ["mediterranean", "coffee", "gallery", "cocktails", "ice_cream", "desserts", "city_center"], "outdoor_seating": true, "indoor_seating": true, "name": "Cvajner", "phone": "+385 52 216 502", "opening_hours": "Mo-Sa 08:00-23:00; Su 10:00-23:00", "addr:housenumber": "2", "addr:street": "Forum", "rating": 4.3, "description": "Art café and gallery on Pula’s main square, known for its striking historic interior, artistic atmosphere, and terrace overlooking the Forum and the Temple of Augustus.", "reviews": ["Great place to get some coffee and quick food; located right in Forum Square, so finding this place is super simple. Service could be a bit better and more organized, but otherwise everything was super tasty.", "Very nice iced coffee. Cozy enviroment, interesting design with restored paintings on the walls.", "This is in a great location if you sit outside. The Forum has a great buzz and is beautiful. Prices are quite reasonable for such a location (big draught beer €4.2) Most of the staff are busy and seem a bit a bit grumpy ( except one nice waitress) There are small menus on the tables and bills are clearly itemised. We saw a family leave after waiting ages to be served. Inside looks nice too with some old frescos. Locals here too. Worth a visit though.", "Gorgeous and cosy caffe... Well preserved historical charm done by keeping the original tapestry and blending it in with the new one. Drinks are well made and the staff is polite, very nice place to come to on a rainy day."], "price": "medium"}}
4. {"type": "hostel", "properties": {"name": "Sol Garden - Hostel with a Soul", "tags": ["hostel", "near_attractions"], "description": "A simple and budget-friendly stay close to Pula Arena and the city’s historic center, offering dormitories and twin rooms with access to shared bathrooms. Guests can use a fully equipped shared kitchen, relax in the garden or on the terrace, and easily reach the waterfront, restaurants, bars and main transport connections on foot.", "rating": 5.0, "reviews": ["The hostel was very clean, it had a pleasant smell, and it was very quiet. It has a large kitchen and a spacious balcony. In the rooms, there are also small lockers that can be locked using the card provided by the reception to access the doors. Nearby, there are 2–3 markets, a coffee bar, and it is also close to the Arena as well as the bus station.", "The hostel is very good, quiet, and has several places nearby such as markets, coffee bars, and other shops. It also has a nice balcony, a large kitchen, and spacious bathrooms. The rooms are clean, air-conditioned, and everything is in order.", "Location and Staff! Excellent environment"]}}
5. {"type": "cafe", "properties": {"tags": ["wine", "cocktails", "beer", "breakfast", "brunch", "sandwiches", "desserts", "ice_cream", "city_center"], "outdoor_seating": true, "indoor_seating": true, "name": "Enoteca Istriana", "phone": "+385 99 323 6541", "opening_hours": "Mo-Su 09:00-21:00", "addr:housenumber": "11", "addr:street": "Forum", "rating": 3.6, "description": "A wine and coffee bar in the heart of Pula’s old town, right on Forum square by the Temple of Augustus, known for its wide selection of Istrian wines and craft beers.", "reviews": ["Visited this wine bar 4 times during our stay in Pula for coffee, wine, ice cream and sandwiches in a relaxed warm friendly atmosphere. The service was fast and efficient provided by staff who were friendly and accommodating. I highly recommend this wine bar will revisit on a return to Pula.", "Very good place for coffee and verry kind staff. Breakfast is good , this is the best place of the square!"], "price": null}}

1. {"type": "camp_site", "properties": {"name": "Arena Stoja", "tags": ["camp", "family_friendly", "coastal", "near_beach", "pet_friendly"], "description": "Seaside campsite on the Stoja peninsula in Pula, offering sea-view pitches, a peaceful natural setting, and direct access to the rocky coast.", "rating": 4.1, "reviews": ["Beautiful campsite on the Adriatic coast. We watched the dolphins in the evenings, which was very impressive. There's a very good restaurant on site, and everything is very clean. The staff at reception are very friendly, and the sanitary facilities are constantly cleaned. The bus to Pula stops right in front of the campsite, and you can also easily walk to the Colosseum in 35 minutes. We really enjoyed our stay here and would love to come back. The only minor drawback is that, unlike most campsites, there are no dog waste bags available anywhere on the grounds. A dog costs €7 per day.", "During our Istria tour in April 2026, we stayed here for two nights in our campervan. Five stars are well-deserved. Everything was clean and very nice. We were parked in the first row right by the sea and enjoyed the sunset. It was very quiet at night, and the staff were very friendly. We would gladly come back.", "Beautiful campsite by the sea. Clean and excellent sanitary facilities. Friendly welcome. Many facilities. Good price."]}}
2. {"type": "cafe", "properties": {"tags": ["mediterranean", "pizza", "pasta", "seafood", "meat", "vegetarian", "city_center"], "outdoor_seating": true, "indoor_seating": true, "name": "Imperium Bistro", "phone": "+385 98 219 530", "opening_hours": "Mo-Su 12:00-22:00", "addr:housenumber": "8", "addr:street": "Forum", "rating": 4.7, "description": "Elegant bistro on Forum square that combines long-standing local tradition with a more modern kitchen, offering refined Mediterranean and seasonal dishes in the heart of Pula.", "reviews": ["With a new manager and chef at the helm, this restaurant is on a trajectory towards success in 2024 and beyond. Their innovative approach to food and hospitality, coupled with a commitment to excellence in every aspect of their operation, sets them apart as a standout destination for food lovers and connoisseurs alike. 💪💪🍻❤️", "Nice restaurant with very romantic atmosphere. The location is amazing. Had seafood plate and loved all the seafood options, but the potatoes tasted weird, for which I am giving a bit less. But the local Istrian delicacies were very tasty! Prosciutto was also amazing.", "This restaurant is superb. You cannot fault it. Service and food were all so good. Our dishes were excellent and the food that was brought to the tables around us looked amazing too. We had traditional Istrian cuisine. I could’ve stayed there all day. This place is a must visit if you’re visiting Pula. Thanks again.", "Really good food, served in a nice manner. The location is also nice, in the old town of Pula. The restaurant is officially closing at 22 hrs, but if you are already at the table, you can continue to enjoy your food without stress (pics made at 22:45 hrs :) ). Thank you for an exquisite evening!"], "price": null}}
3. {"type": "cafe", "properties": {"tags": ["mediterranean", "coffee", "gallery", "cocktails", "ice_cream", "desserts", "city_center"], "outdoor_seating": true, "indoor_seating": true, "name": "Cvajner", "phone": "+385 52 216 502", "opening_hours": "Mo-Sa 08:00-23:00; Su 10:00-23:00", "addr:housenumber": "2", "addr:street": "Forum", "rating": 4.3, "description": "Art café and gallery on Pula’s main square, known for its striking historic interior, artistic atmosphere, and terrace overlooking the Forum and the Temple of Augustus.", "reviews": ["Great place to get some coffee and quick food; located right in Forum Square, so finding this place is super simple. Service could be a bit better and more organized, but otherwise everything was super tasty.", "Very nice iced coffee. Cozy enviroment, interesting design with restored paintings on the walls.", "This is in a great location if you sit outside. The Forum has a great buzz and is beautiful. Prices are quite reasonable for such a location (big draught beer €4.2) Most of the staff are busy and seem a bit a bit grumpy ( except one nice waitress) There are small menus on the tables and bills are clearly itemised. We saw a family leave after waiting ages to be served. Inside looks nice too with some old frescos. Locals here too. Worth a visit though.", "Gorgeous and cosy caffe... Well preserved historical charm done by keeping the original tapestry and blending it in with the new one. Drinks are well made and the staff is polite, very nice place to come to on a rainy day."], "price": "medium"}}
4. {"type": "cafe", "properties": {"tags": ["coffee", "wine", "cocktails", "city_center"], "outdoor_seating": true, "indoor_seating": true, "name": "Sirena", "phone": null, "opening_hours": "Mo-Fr 08:00-24:00; Sa-Su 09:00-24:00", "addr:housenumber": "12", "addr:street": "Forum", "rating": 4.1, "description": "A relaxed café on Pula’s main square, offering coffee, wine, cocktails, and terrace seating with views of the historic Forum.", "reviews": ["Wonderful place for coffee or a glass of delicious wine, with a view of the beautiful buildings around Forum Square. During our visits, we had the pleasure to meet waitress with long, slightly wavy hair — she was sooo cool and perfectly handled all orders. We'd love to come back! ❤️", "Nice terrace on the square! During the day, lots of shadow because of the wide parasols! The square is open, don’t get sunburned !", "Nice place, amazing coctails and lovely staff!"], "price": null}}
5. {"type": "cafe", "properties": {"tags": ["international", "pancakes", "waffles", "vegetarian"], "outdoor_seating": false, "indoor_seating": true, "name": "Pulačinka", "phone": "+385 52 825 825", "opening_hours": "Mo-Tu 14:00-22:00; We-Su 10:00-23:00", "addr:housenumber": "5", "addr:street": "Istarska", "rating": 4.6, "description": "A cozy dessert and pancake cafe in the center of Pula, known for sweet and savory pancakes, waffles, churros, and other treats. Guests can customize their own pancake with a wide range of spreads, toppings, fruit, biscuits, and chocolate bars, making it a popular spot for breakfast, dessert, or a casual snack.", "reviews": ["We had very tasty dessert here, a giant pancake and a wafle. Both were packed with sweet things full of calories 😀 You can select from pre-set variations of sweet or salty pancakes, or you can create your own version.", "This creperie is absolutely amazing! The pistachio sauce is the best I’ve ever had – rich, creamy, and full of flavor. On top of that, the staff are incredibly friendly and attentive, which makes the whole experience even better. Highly recommended!", "We have tried churros and custom pancake. Churros were good, but not the best that we had. But pancake was almost perfect. It was done quickly without saving on ingredients. There are many different ingredients to choose from and you can mix as much as you want. Prices are high but it is normal for Pula I guess..", "I've eaten here a palačinka with my girlfriend and it was the most Nutella I ate in a long time. Then, she had a blood sugar spike so powerful she drove 360 km without any pause. Recommended before long road trips 👍🏻"], "price": "medium"}}

1. {"type": "fort", "properties": {"name": "Utvrda Marie Louise", "tags": ["fortress", "historic", "coastal", "panoramic_view", "military_history"], "description": "Large 19th-century coastal fortress on the Muzil peninsula in Pula, known for its circular design and strategic views over the bay entrance.", "rating": 4.4, "reviews": ["The remains of a large defensive fort on Musil peninsula. It was built in the 19th century and used by different armies throughout history. Today it is almost forgotten but still far from a mere ruin. The strength of its walls and beauty of its architecture are still evident. It is safe to explore, yet watch your step for scrap metal, holes and other obstacles. Just like Verudela this ruin should be restored and put to good use.", "Spectacular abandoned fort. You can explore everything. Be careful.", "There's a good, convenient entrance, but it's guarded. Closed to the curious. However, you can access the area along the western coast along a narrow path. Along the way, you'll encounter abandoned former military fortifications. It's a bit scary! Once inside, I felt like a stalker! I saw several huge peacocks. This was once a huge military base. Now everything is abandoned, but the buildings, both above and below ground, are in excellent condition."]}}
2. {"type": "fort", "properties": {"name": "Fort Ovine", "tags": ["fortress", "historic", "military_history", "coastal"], "description": "Abandoned Austro-Hungarian coastal fort in the Valovine area, known for its atmospheric tunnels, overgrown walls, and striking rooftop views over the sea.", "rating": 4.4, "reviews": ["It was a small ruin with an entrance, a hallway, some rooms and a tunnel to a small katacomb. The dark tunnel which looks like the entrance of a katacomb has a slight slope and is slippery. Unfortunately some of the rooms were used as toilets - no understanding for that... The parking lots are kind off in front of fort and very busy. So make shure to plan your visit in the morning.", "Nothing special about this place, I have only visited the exterior though. I don't know if I suggest the visit. There is a civil guard near the entrance", "A fortification overgrown in the rock. Large areas are empty and dark. For those who enjoy extreme sports, this is for you."]}}
3. {"type": "fort", "properties": {"name": "Fort Brioni Minor", "tags": ["fortress", "historic", "coastal", "military_history", "national_park", "island", "events"], "description": "Large Austro-Hungarian coastal fortress on Mali Brijun, known for its preserved military architecture, strategic sea-facing position, and summer theatre performances held within the fort.", "rating": 4.8, "reviews": ["We have a chance to enjoy there as part of the King Lear play. Fortress is amasing an perfectly fitted the show.", "Amazing still standing fortress from the beginning of 20th century. Used by Ulysses theatre", "A beautiful place, lots of wonderful things to see, from rich flora and fauna to beautiful historical buildings."]}}
4. {"type": "fort", "properties": {"name": "Fort Verudella", "tags": ["fortress", "historic", "coastal", "aquarium", "military_history", "family_friendly"], "description": "19th-century coastal fortress on Punta Verudela, now home to Aquarium Pula and known for its military heritage and sea-facing setting.", "rating": null, "reviews": null}}
5. {"type": "castle", "properties": {"name": "Fort Kaiser Franz", "tags": ["fortress", "historic", "coastal", "military_history", "island", "closed_area"], "description": "Historic coastal fortress on the island of Sveti Andrija in Pula, known for its circular form, layered military history, and strategic position in the middle of the harbour.", "rating": 3.8, "reviews": ["Nice fort. It's a pity that it is neglected and completely overgrown. While sightseeing, it feels like walking through a jungle. There are a lot of snakes and rats. On the roof of the fortress there are a lot of hidden ventilation holes through which you can fall, so you need to be very careful."]}}

1. {"type": "cafe", "properties": {"tags": ["coffee", "pub", "beer", "city_center"], "outdoor_seating": true, "indoor_seating": true, "name": "Bounty", "phone": "+385 52 218 088", "opening_hours": "Mo-Su 07:00-23:00", "addr:housenumber": "8", "addr:street": "Veronska", "rating": 4.6, "description": "A cozy Irish-style pub in city center, known for draft beer, a wide drink selection, and a comfortable terrace with a relaxed atmosphere.", "reviews": ["An excellent Irish pub with a great Irish atmosphere. Clean, tidy, good to be here As it is a bit away from the busy tourist area, it is not crowded. Guinness and local beers on tap, plus a great selection of drinks. Shaded, comfortable terrace.", "Didn't get to stay here for long (one drink) however it has a real homely feel to the place and is a really nicely situated pub. Good atmosphere and seating options, good drink choices which are more foreign options (Guinness/Heineken/Jack Daniels etc) and the prices are quite good also! Would recommend stopping in for some drinks if in the local area!", "This is a proper bar. Beautiful inside. A nice seating area outside. They have a really good selection of drinks on offer."], "price": null}}
2. {"type": "pub", "properties": {"tags": ["coffee", "cocktails", "beer", "nightlife", "city_center"], "outdoor_seating": true, "indoor_seating": true, "name": "Old City Bar", "phone": "+385 52 222 944", "opening_hours": "Mo-Fr 06:30-02:30; Sa 07:00-02:00; Su 08:30-2:30", "addr:housenumber": "1", "addr:street": "Danteov trg", "rating": 4.5, "description": "A pub located in the center of Pula, offering a relaxed atmosphere during the day and lively parties at night. It is a popular spot for drinks, socializing, and weekend nightlife.", "reviews": ["Great service, Marcus was attentive and funny and made our night!! Drinks were all very good and really enjoyed the theatrics of the different shots and cocktails.", "Best Cocktails in town and super cool service personal, Marcus is our man! Come here! ✨🙌", "The service in this place cannot be compared to anything I've experienced so far of my nine days in Croatia. Not the cheapest, but the persistence and effort by Marco is why you pay a premium. The live music was also quite good. Awsome Bloody Mary if you're into that, and a selection of craft beer if that is your thing. (To Marco's employer, you should give this man a raise)"], "price": "medium"}}
3. {"type": "cafe", "properties": {"tags": ["coffee", "cocktails", "beer", "wine", "city_center"], "outdoor_seating": true, "indoor_seating": true, "name": "Caffe Bar Uliks", "phone": "+385 52 219 158", "opening_hours": "Mo-Su 07:00-02:00", "addr:housenumber": "1", "addr:street": "Trg Portarata", "rating": 4.5, "description": "A historic café bar in the very center of Pula, right next to the Arch of the Sergii, known for its literary connection to James Joyce, a wide drinks selection, specialty local spirits and craft beers, and a lively atmosphere with quizzes and other events.", "reviews": ["Would highly recommend! Really nice people inside and great vibes. The decor is so cool!", "Really lovely small pub, 10/10 would recommend for a quick pint. Cool statue of James Joyce outside who used to teach English in the building back yonder.", "Best place to watch Pula‘s life, friendly service, reasonable prices, my recommendation: the Negroni", "A nice cup of coffee on a beautiful spot next to the Arch of the Sergii."], "price": "medium"}}
4. {"type": "zoo", "properties": {"name": "Fazanerija", "tags": ["zoo", "animals", "family_friendly", "national_park", "island"], "description": "Small animal and bird area where visitors can see peacocks, turkeys, guinea fowl, parrots, and other birds, while the site also serves as a recovery and temporary care center for wild animals.", "rating": 4.1, "reviews": ["Don’t miss seeing this bird! Easy to find, unique experience", "Koji is awesome! He knows a few words, best one being 'tito'", "The animals seem content, and the facility was well-maintained. Of course, the buildings are old, and it's not a large zoo. But it's definitely worth a visit."]}}
5. {"type": "restaurant", "properties": {"tags": ["international", "grill", "meat", "pasta", "burgers", "beer", "wine", "cocktails", "vegetarian", "city_center"], "outdoor_seating": false, "indoor_seating": true, "name": "Kinema", "phone": "+385 99 164 4949", "opening_hours": "Mo-Th 10:00-23:00, Fr,Sa 10:00-24:00, Su 12:00-23:00", "addr:housenumber": "12", "addr:street": "Flavijevska", "rating": 4.7, "description": "A modern pub and restaurant in Pula with a lively social atmosphere, combining great food, drinks, and entertainment in one place. Kinema is known for billiards, darts, live sports screenings, themed events, burgers, steaks, breakfast, local wines, cocktails, and craft beer, making it a popular spot for both casual hangouts and nights out with friends.", "reviews": ["Fantastic bar/restaurant. Visiting from England I was looking for somewhere to watch the Aston Villa match, walked in I believe I met the owner, said he had the game on, minute later a guy came over and said you want the Villa game on the big screen, yes I said, that’s great hospitality! The bar is extremely cool, strangely it smells wonderful in there, darts, pool all can be played. Food is excellent, we had a grazing board and chicken wings, spot on they was. Staff, really friendly and welcoming, sorry about this as I couldn’t remember her name, but Drag….. was first class.", "One of the best restaurants in Pula, especially if you’re looking for a place to eat near the Pula Arena. The food portions were huge, definitely more than enough for one person, and we left feeling very full and satisfied. The drinks were excellent and had a classy touch. The ambiance was fantastic, with great entertainment and we didn’t even realize we had stayed for over 3 hours! Highly recommended.", "What a venue! If you are looking for live sports, pool, darts or just a good atmosphere, head here. An old cinema has been transformed into a superb sports bar. A small doorway opens up to this vast multi room venue, and the screen is maaaasssssiiiiiiiivvveee. A nice welcome to fast knowledgeable service & they go to every effort to accommodate your needs. After the large main room, there's a pool room off to one side & another more intimate balcony area upstairs. The atmosphere is not too loud, so you have to shout, and the other guests are all smiling and up to banter. The menu does not do justice to the food, which was excellent. A mix of burgers, etc, to more traditional dishes Generous portios, to say the least, could not even look at the desserts menu. A real gem * kids are welcome", "This was the best restaurant I've visited in Pula. Pavle, the server was extremely pleasant and welcoming, he gave some great suggestions. I came in only to have some coffee but ended up getting the breakfast and dessert. Couldn't tell which was better. Extremely well made food, with even better staff. I couldn't recommend this place more!"], "price": "medium"}}

1. {"type": "cafe", "properties": {"tags": ["coffee", "ice_cream", "cocktails", "sandwiches", "desserts", "city_center"], "outdoor_seating": true, "indoor_seating": true, "name": "Kukuriku", "phone": "+385 52 210 498", "opening_hours": "Mo-Th 07:00-23:00; Fr-Sa 07:00-24:00; Su 07:30-23:00", "addr:housenumber": "7", "addr:street": "Istarska", "rating": 4.0, "description": "A relaxed city-center café, offering coffee, cocktails and casual sweet and savory snacks in a pleasant outdoor setting.", "reviews": ["Nice place, friendly waiter and really tasty food", "Loved this place! It has really good chocolate croissants and the cappuccino is also very good.", "Nice place in city center. A bit pricey. Aperol spritz 8eur, Hugo the same. Staff was nice and professional."], "price": "medium"}}
2. {"type": "cafe", "properties": {"tags": ["coffee", "city_center"], "outdoor_seating": true, "indoor_seating": true, "name": "Caffe Bar Cedar", "phone": "+385 34 872 624", "opening_hours": "Mo-Su 08:00-24:00", "addr:housenumber": "40", "addr:street": "Kandlerova", "rating": 3.8, "description": null, "reviews": null, "price": null}}
3. {"type": "cafe", "properties": {"tags": ["bakery", "breakfast", "coffee", "pizza", "sandwiches", "desserts", "vegetarian", "city_center"], "outdoor_seating": false, "indoor_seating": true, "name": "Mlinar", "phone": null, "opening_hours": "Mo-Fr 06:30-20:00; Sa 06:30-15:00; Su 07:00-15:00", "addr:housenumber": "9", "addr:street": "Narodni trg", "rating": 3.8, "description": "A casual Mlinar cafe next to the city market, offering baked goods, pastries, sandwiches, and self-service coffee in a simple indoor seating area. It is a convenient spot for a quick breakfast, snack, or coffee break in the city center.", "reviews": ["Everything I've gotten to eat at any Mlinar has been delicious and a good price. I usually avoid chains, but they're just so good!", "Unfortunately the coffee is produced by an automatic machine... So nothing really special The food is okeish, I cannot complain. If you are hungry and you cannot find anything else around, this place will be fine.", "Good bakery, but coffe is overpriced (2 eur for coffe in paper cup?). 🙄Price of yoghurt is also quite high (1.8 eur) - I remember the times then normal price was 0.4 eur (few years ago). 🤑 I had a chicken burek here and I was suprised that I liked it more than traditional one ( with beef )"], "price": "medium"}}
4. {"type": "zoo", "properties": {"name": "Fazanerija", "tags": ["zoo", "animals", "family_friendly", "national_park", "island"], "description": "Small animal and bird area where visitors can see peacocks, turkeys, guinea fowl, parrots, and other birds, while the site also serves as a recovery and temporary care center for wild animals.", "rating": 4.1, "reviews": ["Don’t miss seeing this bird! Easy to find, unique experience", "Koji is awesome! He knows a few words, best one being 'tito'", "The animals seem content, and the facility was well-maintained. Of course, the buildings are old, and it's not a large zoo. But it's definitely worth a visit."]}}
5. {"type": "cafe", "properties": {"tags": ["coffee", "desserts", "pancakes", "cakes", "sandwiches"], "outdoor_seating": true, "indoor_seating": true, "name": "Cookie", "phone": null, "opening_hours": "Mo-Su 09:00-22:00", "addr:housenumber": "14A", "addr:street": "Stoja", "rating": null, "description": "A modern café bar in Max City on Stoja with a spacious terrace, sea views, and a casual setting for coffee, desserts, and light meals.", "reviews": null, "price": "medium"}}

1. {"type": "fort", "properties": {"name": "Mletačka utvrda", "tags": ["fortress", "historic", "panoramic_view", "city_center", "events", "concerts"], "description": "French-style defensive fortress built by the Venetians in the 1600s, with views of the city & bay.", "rating": 4.5, "reviews": ["Amazing views from the top - panoramic of the whole site - was helpful as my first look of the city to get my bearings. Loved that the ticket also included use of the undercity tunnel network - helpful as it was raining on and off (visited a couple of days ago!)", "Very beautiful views. Nice fortress, with a tower from where the views are even more wonderful. The entrance fee is 7 euros.", "I like history and I've been to quite a few other fortresses and the design follows other fortress designs because you're trying to defend and required similar designs and systems. The fortress has been disarmed and the museums/displays on site are bright with information and displays but I found some lack.....that is not a bad comment, just a minor con. There has obviously been a lot of work to maintain the integrity of the stone work and that is definitely a pro. Definitely worth the time for a visit. I rate this 4 stars."]}}
2. {"type": "hostel", "properties": {"name": "Hostel Art & Joy", "tags": ["hostel", "free_parking", "garden", "family_friendly"], "description": "Friendly hostel in Pula with a garden, terrace, shared kitchen, and convenient access to the Arena and other city attractions.", "rating": 3.8, "reviews": ["We had an amazing stay in this hostel. The staff is very nice and helpful : the receptionist gave us tips on what to see and visit around the city, helped us book bikes. We were also able to change beds to be closer to each other in the room. The bedrooms and common rooms are cleaned daily and the air conditioning was appreciated. The hostel is well located, there are bus stops right next to it, it’s only a 10-minutes walk to the city center. As 2 girls travelling, we felt very confortable and safe staying at this hostel. People we met there were easygoing and we had some really nice times in the kitchen and on the terrace. To sum up : we had a wonderful vacation in Pula :) PS : the only thing that’s missing would be board games accessible to everyone.", "We had a nice stay in the private room. Everything is clean, the staff is friendly, pizzeria next door. The cute mosaique and artistic flair got us lost in long conversations about art and the meaning of life ;)", "I have stayed in Pula 5 times now. The first time was at an apartment with restricted check in times. 3pm to 5pm only. And a long walk to the centre.I was in a restaurant chatting to someone on the next table.He recommended Art and Joy hostel. I took a walk there the next day. His advice was spot on. I met the manager there and said may I have a look inside, with a possibility of staying there the following year. She agreed. Wow it was great I thought. So I booked for the next Summer. I wasn't disappointed. I have now stayed 4 times each Summer for 4 years.Close to the centre, and the staff are superb. They will help you with any issues you may have.. The hard working cleaner is great also. I recommend it. Choice of rooms to suit your requirements.And good value.. Give it a try for a few nights and then extend it if you want to. Obviously subject to availability."]}}
3. {"type": "hostel", "properties": {"name": "Sol Garden - Hostel with a Soul", "tags": ["hostel", "near_attractions"], "description": "A simple and budget-friendly stay close to Pula Arena and the city’s historic center, offering dormitories and twin rooms with access to shared bathrooms. Guests can use a fully equipped shared kitchen, relax in the garden or on the terrace, and easily reach the waterfront, restaurants, bars and main transport connections on foot.", "rating": 5.0, "reviews": ["The hostel was very clean, it had a pleasant smell, and it was very quiet. It has a large kitchen and a spacious balcony. In the rooms, there are also small lockers that can be locked using the card provided by the reception to access the doors. Nearby, there are 2–3 markets, a coffee bar, and it is also close to the Arena as well as the bus station.", "The hostel is very good, quiet, and has several places nearby such as markets, coffee bars, and other shops. It also has a nice balcony, a large kitchen, and spacious bathrooms. The rooms are clean, air-conditioned, and everything is in order.", "Location and Staff! Excellent environment"]}}
4. {"type": "museum", "properties": {"name": "Zerostrasse", "tags": ["museum", "historic", "military_history", "city_center", "near_attractions", "family_friendly"], "description": "Underground tunnel complex beneath central Pula, created as a wartime shelter system during the Austro-Hungarian period and today presented as a historic site known as Zerostrasse.", "rating": 4.3, "reviews": ["Nice tunnel system that is easy to navigate. There seems to be very little information about the tunnels themselves and more information about various things that happened in Pula around the area. Tickets to the tunnel gove you access to the fort above.", "Tunnels underneath the citadel with access to the citadel included in the price if you work your way up. I did this in reverse and made my way down through the tunnels. Blissfully cool after the heat of the exterior. Fascinated by the tunnels and side rooms. Would have liked to see more information provided on their wartime use, and not just learn about the trams. Found a lovely piece of art painted onto a wall in one of the side rooms, left there by a previous resident who had tried to bring a little of the outside indoors perhaps? A little forgotten masterpiece just waiting to be discovered. Just kind of stumbled across it as I explored, but maybe should have been signposted with a bit of context provided. The tunnels exit at locations in the old town. As a tourist myself this left me almost instantly in the shopping area at the end of my visit. I am sure not the original builders intention, but very welcome for someone like myself trying to get the most out of their day.", "Fascinating underground tunnels. Zerostrasse is a network of WWI-era tunnels beneath Pula, originally built as shelters. It’s a cool and quiet escape from the summer heat, with interesting historical displays along the way. Not a long visit, but definitely worth it if you're curious about the city's wartime past."]}}
5. {"type": "hotel", "properties": {"name": "Amfiteatar", "tags": ["hotel", "city_center", "restaurant", "near_attractions"], "description": "Boutique hotel in central Pula, just steps from the Arena, offering modern rooms, a well-known restaurant, and easy access to the old town and waterfront.", "rating": 4.2, "reviews": ["Fantastic hotel, great location, very central. Lovely staff and extremely helpful with suggestions to eat and drink and booking a taxi to the airport. Room 101 was great, really spacious with bathrobes and slippers. Tea and coffee making facilities in the room. Great choice of both hot and cold food at breakfast. Would definitely stay again.", "I can’t get over what a great place this is! Location of course, front desk service, comfort, and value. I would highly recommend this facility for any type of visit to Pula.", "Great experience staying here! Location is superb and the staff is super friendly. We accidentally broke the tap in the bathroom while staying here, but the hotel staff just exchanged it during the day and it was fixed when we got back in the afternoon. Would definitely recommend staying here!"]}}

1. {"type": "aquarium", "properties": {"name": "Aquarium Pula", "tags": ["aquarium", "fortress", "family_friendly", "historic", "near_beach"], "description": "Aquarium in Fort Verudela and Battery San Giovanni in Pula, known for its Adriatic and exotic marine exhibits, sea turtle rescue centre, and unique setting within historic Austro-Hungarian fortifications.", "rating": 4.5, "reviews": ["We (family of 7) visited during the holiday season. The price was excellent (half price period), there were not many people. We bought the tickets online, in advance. The whole experience was great, totally worth the trip from Rovinj. There are two exhibitions, international and mediterranean. Both were quite enjoyable. The only problem was that we have a dog, who is not allowed inside. It is absolutly understandable (however there are even zoos, where they are welcome: like in Ljubljana Zoo), and the surrounding area is excellent for walks, so we diveded our forces, and went in separately, in two groups. Not ideal, but it was a great decision not to miss the aquarium. Recommended!", "We had such a great time here. It was late September and really not too many people. The building (old fortress) ia very impressive and the perfect location for this beautiful Aquarium. It consists of two buildings, old tunnels and areas outside. Our daughter loved it and we did too. 100% recommend", "This was a wonderful surprise! I didn’t expect it to be so big and to have so many different species. My 9-month-old loved it and was fascinated by everything. I highly recommend bringing your family here and buying tickets online, as the regular line can get quite long, while the online ticket line was empty."]}}
2. {"type": "beach", "properties": {"name": "Ambrela Beach", "tags": ["beach", "pebble", "crowdy", "family_friendly"], "description": "Popular pebble beach on Verudela in Pula, known for its shallow sea access, family-friendly setting, nearby parking, and a wide range of beach facilities and water activities.", "rating": 4.3, "reviews": ["It was crowded, even though we were here after rain. It gets deep quickly, there were thousands of small jellyfish in the water, it was strange at first, but you get used to it. We were able to park for free at ARTPARK, although it is difficult to find a free space. Nice, clean beach, there is a side beach, showers are free.", "Clean water, pebble beach. But very crowded in summer.", "A gorgeous beach. The surrounding area is beautiful and clean. There's a couple of meters of sandy entry into the water. Otherwise, there are rocks all around, so protect your feet!", "A very nice beach. Crystal-clear water. Not cold. A food and drink stand. Restrooms. Everything you need for a day out."]}}
3. {"type": "beach", "properties": {"name": "Plaža Jupiter", "tags": ["beach", "island", "stone", "paved", "national_park", "family_friendly"], "description": "Well-maintained designated beach on Veli Brijun, known for its stone-paved shore, two spacious terraces, and relaxing atmosphere. It is one of the official swimming areas on the island, appreciated for its cleanliness, safety, and beautiful sunset views.", "rating": 4.1, "reviews": ["Jupiter Beach on Brijuni Island in Croatia is a true paradise! The water is crystal clear and ideal for children to swim and play safely. For snorkeling enthusiasts, this beach is an absolute dream – you can observe countless fish in their natural habitat. A perfect place to enjoy the beauty of the underwater world. Highly recommended!", "Cozy little beach"]}}
4. {"type": "fort", "properties": {"name": "Battery San Giovanni", "tags": ["fortress", "historic", "coastal", "military_history"], "description": "Historic coastal battery above Verudela in Pula, built as part of the Austro-Hungarian defence system and known for its ramparts, military character, and location near Aquarium Pula and the beaches.", "rating": 4.8, "reviews": ["Very beautifully made and presented. This facility houses the second part of the aquarium, which gathers more exotic animal species and provides a look at the development and power of the Austro-Hungarian Navy. I was enchanted by everything I saw in both facilities. You should definitely visit the Pula Aquarium. It is relaxing, inspiring, enchanting. Highly recommended.", "The second part of the aquarium is located in the Baterija San Giovanni. Tickets must be purchased at the upper level. This section of the aquarium is dedicated to 'exotic' animal species and concludes with a marine exhibit. The aquariums are well worth seeing. Our children were thrilled. Important on hot days... the aquarium is air-conditioned. The conversion of the fort into an aquarium is also very well done. In short: absolutely worth seeing.", "The second part of the aquarium, with the larger animals."]}}
5. {"type": "fort", "properties": {"name": "Fort Brioni Minor", "tags": ["fortress", "historic", "coastal", "military_history", "national_park", "island", "events"], "description": "Large Austro-Hungarian coastal fortress on Mali Brijun, known for its preserved military architecture, strategic sea-facing position, and summer theatre performances held within the fort.", "rating": 4.8, "reviews": ["We have a chance to enjoy there as part of the King Lear play. Fortress is amasing an perfectly fitted the show.", "Amazing still standing fortress from the beginning of 20th century. Used by Ulysses theatre", "A beautiful place, lots of wonderful things to see, from rich flora and fauna to beautiful historical buildings."]}}

1. {"type": "monument", "properties": {"name": "Slavoluk Sergijevaca", "tags": ["monument", "roman", "historic", "landmark", "city_center"], "description": "Historic Roman arch in central Pula, known as the Arch of the Sergii or Golden Gate, famous for its ornate reliefs and long-standing civic significance.", "rating": 4.6, "reviews": ["The Golden Gate in Pula is a beautifully preserved historic landmark. Its Roman architecture and detailed stonework make it a must-see in the city center. A great spot for a quick walk, photos, and soaking in the ancient atmosphere.", "A Roman triumphal arch, beautifully intact through the ages. Its intricate carvings reflect the artistry of the Augustan era, while its enduring form stands as a testament to the power and legacy of ancient Rome.", "Beautiful Roman arch in the heart of Pula. The Arch of the Sergii is a stunning reminder of the city's ancient past. Great spot for photos and easy to find while walking through the old town.", "Another beautiful piece of history which must be seen to be appreciated when you’re in Pula. Seems to be the main entrance essentially to the late ish night shops and restaurants/bars etc. Did have a nice jazz band situated here one night too!"]}}
2. {"type": "cafe", "properties": {"tags": ["coffee", "pub", "beer", "city_center"], "outdoor_seating": true, "indoor_seating": true, "name": "Bounty", "phone": "+385 52 218 088", "opening_hours": "Mo-Su 07:00-23:00", "addr:housenumber": "8", "addr:street": "Veronska", "rating": 4.6, "description": "A cozy Irish-style pub in city center, known for draft beer, a wide drink selection, and a comfortable terrace with a relaxed atmosphere.", "reviews": ["An excellent Irish pub with a great Irish atmosphere. Clean, tidy, good to be here As it is a bit away from the busy tourist area, it is not crowded. Guinness and local beers on tap, plus a great selection of drinks. Shaded, comfortable terrace.", "Didn't get to stay here for long (one drink) however it has a real homely feel to the place and is a really nicely situated pub. Good atmosphere and seating options, good drink choices which are more foreign options (Guinness/Heineken/Jack Daniels etc) and the prices are quite good also! Would recommend stopping in for some drinks if in the local area!", "This is a proper bar. Beautiful inside. A nice seating area outside. They have a really good selection of drinks on offer."], "price": null}}
3. {"type": "zoo", "properties": {"name": "Fazanerija", "tags": ["zoo", "animals", "family_friendly", "national_park", "island"], "description": "Small animal and bird area where visitors can see peacocks, turkeys, guinea fowl, parrots, and other birds, while the site also serves as a recovery and temporary care center for wild animals.", "rating": 4.1, "reviews": ["Don’t miss seeing this bird! Easy to find, unique experience", "Koji is awesome! He knows a few words, best one being 'tito'", "The animals seem content, and the facility was well-maintained. Of course, the buildings are old, and it's not a large zoo. But it's definitely worth a visit."]}}
4. {"type": "pub", "properties": {"tags": ["coffee", "cocktails", "beer", "nightlife", "city_center"], "outdoor_seating": true, "indoor_seating": true, "name": "Old City Bar", "phone": "+385 52 222 944", "opening_hours": "Mo-Fr 06:30-02:30; Sa 07:00-02:00; Su 08:30-2:30", "addr:housenumber": "1", "addr:street": "Danteov trg", "rating": 4.5, "description": "A pub located in the center of Pula, offering a relaxed atmosphere during the day and lively parties at night. It is a popular spot for drinks, socializing, and weekend nightlife.", "reviews": ["Great service, Marcus was attentive and funny and made our night!! Drinks were all very good and really enjoyed the theatrics of the different shots and cocktails.", "Best Cocktails in town and super cool service personal, Marcus is our man! Come here! ✨🙌", "The service in this place cannot be compared to anything I've experienced so far of my nine days in Croatia. Not the cheapest, but the persistence and effort by Marco is why you pay a premium. The live music was also quite good. Awsome Bloody Mary if you're into that, and a selection of craft beer if that is your thing. (To Marco's employer, you should give this man a raise)"], "price": "medium"}}
5. {"type": "fort", "properties": {"name": "Fort Punta Christo", "tags": ["fortress", "historic", "coastal", "underground", "events", "military_history"], "description": "Circular fort built in the late 1800s with underground rooms, also a venue for music festivals.", "rating": 4.3, "reviews": null}}

1. {"type": "attraction", "properties": {"name": "Avion-vjetrokaz", "tags": ["attraction", "aviation"], "description": "Outdoor aviation attraction near Pula at the Medulin sports airfield, featuring a former light aircraft mounted as a wind vane and memorial display celebrating local flying heritage.", "rating": null, "reviews": null}}
2. {"type": "attraction", "properties": {"name": "LABIRINT MOĆI", "tags": ["attraction", "labyrinth", "meditative", "nature", "stone"], "description": "Stone labyrinth in Šijanska šuma designed for reflective walking, relaxation, and a symbolic experience connected with strength, focus, and inner balance.", "rating": null, "reviews": null}}
3. {"type": "artwork", "properties": {"name": "Marko Marulić", "tags": ["statue", "sculpture", "monument", "park", "artwork", "city_center"], "description": "A bronze public sculpture dedicated to one of the most important figures of Croatian literature, placed in a small park near the waterfront and the railway station. Its calm, dignified form reflects the intellectual and cultural legacy of the Renaissance writer, adding a literary and commemorative note to the surrounding urban landscape.", "rating": 4.0, "reviews": null}}
